const AU_MAX_COORD = Number(AU_LIMITS.max_abs_coordinate_m);
const AU_MIN_DIM = Number(AU_LIMITS.min_dimension_m);
const AU_MAX_DIM = Number(AU_LIMITS.max_dimension_m);
const AU_NOT_SPECIFIED = 'NOT_SPECIFIED';

/* ------------------------------------------------------------- أدوات --- */
function _auEnum(v){ return (typeof v==='string')?v.toUpperCase():null; }
const AU_EDGE_WORDS={N:'N',S:'S',E:'E',W:'W',NORTH:'N',SOUTH:'S',EAST:'E',WEST:'W'};
/* حافّة معلنة فقط. لا يُقتطَع أوّل حرف من نصّ عشوائي: NORTHWEST ليست N. */
function _auEdge(v){ const e=_auEnum(v);
  return (e!==null&&Object.prototype.hasOwnProperty.call(AU_EDGE_WORDS,e))
    ?AU_EDGE_WORDS[e]:null; }
function _auNum(v){
  if(v===null||v===undefined||typeof v==='boolean') return null;
  if(typeof v!=='number'&&typeof v!=='string') return null;
  return _snum(v); }
function _auQ(v){ const r=_pyRound(Number(v),6); return r===0?0:r; }
function _auCanon(o){ return ingestCanonicalJson(o); }
function _auSha16(o){ return sha256Hex(_auCanon(o)).slice(0,16); }
function _auCopy(v){ return (v&&typeof v==='object')?JSON.parse(JSON.stringify(v)):v; }
function auSeverityOf(code){
  return Object.prototype.hasOwnProperty.call(AU_ISSUE_SEVERITY,code)
    ?AU_ISSUE_SEVERITY[code]:'ERROR'; }
function _auIssue(code,subject,detail){
  return {code:code,severity:auSeverityOf(code),
    subject:(subject===null||subject===undefined)?null:String(subject),
    detail:(detail===null||detail===undefined)?null:String(detail)}; }
function _auSortIssues(issues){
  const rank={}; AU_SEVERITIES.forEach((s,i)=>{rank[s]=i;});
  return issues.slice().sort((a,b)=>{
    const ra=-(rank[a.severity]||0), rb=-(rank[b.severity]||0);
    if(ra!==rb) return ra<rb?-1:1;
    if(a.code!==b.code) return _scmp(a.code,b.code);
    const sa=String(a.subject), sb=String(b.subject);
    if(sa!==sb) return _scmp(sa,sb);
    return _scmp(String(a.detail),String(b.detail)); }); }
function _auHasError(issues){ return issues.some(i=>i.severity==='ERROR'); }
function _auResult(issues,extra){
  const out={valid:!_auHasError(issues),issues:_auSortIssues(issues.slice())};
  if(extra) Object.keys(extra).forEach(k=>{out[k]=extra[k];});
  return out; }

function auModelHash(model,scope,buildingId){
  return sha256Hex(_auCanon({scope:scope||'building',
    building_id:buildingId||'bld_0',model:model})); }
function _auShort(h){ return String(h).slice(0,24); }

/* ------------------------------------------------------------ الأمن ---- */
function _auScan(value,depth,path){
  depth=depth||0; path=path||'payload';
  const issues=[];
  if(depth>Number(AU_LIMITS.max_nesting_depth)){
    issues.push(_auIssue('PAYLOAD_REJECTED',path,'nesting is too deep')); return issues; }
  if(Array.isArray(value)){
    if(value.length>Number(AU_LIMITS.max_parameter_keys)*8)
      issues.push(_auIssue('PAYLOAD_REJECTED',path,'array is too large'));
    value.forEach((x,i)=>{ issues.push.apply(issues,_auScan(x,depth+1,path+'['+i+']')); });
    return issues; }
  if(value&&typeof value==='object'){
    const keys=Object.keys(value);
    if(keys.length>Number(AU_LIMITS.max_parameter_keys))
      issues.push(_auIssue('PAYLOAD_REJECTED',path,'too many keys'));
    keys.forEach(k=>{
      const ks=String(k);
      if(AU_FORBIDDEN_KEYS.indexOf(ks)>=0){
        issues.push(_auIssue('PAYLOAD_REJECTED',ks,
          'forbidden key rejected before any processing')); return; }
      if(ks.length>Number(AU_LIMITS.max_string_length)){
        issues.push(_auIssue('PAYLOAD_REJECTED',path,'key is too long')); return; }
      issues.push.apply(issues,_auScan(value[k],depth+1,path+'.'+ks)); });
    return issues; }
  if(typeof value==='string'){
    if(value.length>Number(AU_LIMITS.max_string_length))
      issues.push(_auIssue('PAYLOAD_REJECTED',path,'string is too long'));
    const low=value.toLowerCase();
    for(let i=0;i<AU_FORBIDDEN_VALUES.length;i++)
      if(low.indexOf(String(AU_FORBIDDEN_VALUES[i]).toLowerCase())>=0){
        issues.push(_auIssue('PAYLOAD_REJECTED',path,
          'value carries an executable or unsafe pattern')); break; }
    return issues; }
  if(typeof value==='boolean'||value===null||value===undefined) return issues;
  if(typeof value==='number'){
    if(!isFinite(value)) issues.push(_auIssue('INVALID_PARAMETER',path,
      'a non-finite number is not a coordinate'));
    return issues; }
  issues.push(_auIssue('PAYLOAD_REJECTED',path,'unsupported value type'));
  return issues; }
function _auCoordOk(v){ const n=_auNum(v); return n!==null&&Math.abs(n)<=AU_MAX_COORD; }

/* --------------------------------------------- تحديد موضع النموذج ------ */
function _auTemplates(model){ return (model&&model.floors)||{}; }
function _auRoomsOf(model,t){ const f=_auTemplates(model)[t]||{}; return f.rooms||[]; }
function _auFindRoom(model,t,rid){
  const rooms=_auRoomsOf(model,t);
  for(let i=0;i<rooms.length;i++) if(String(rooms[i].id)===String(rid)) return rooms[i];
  return null; }
function _auAllRooms(model){
  const out=[];
  Object.keys(_auTemplates(model)).sort(_scmp).forEach(t=>{
    _auRoomsOf(model,t).forEach(r=>out.push([t,r])); });
  return out; }
function _auSpaceKey(bid,t,rid){ return bid+'.'+t+'.'+rid; }

const AU_OPENING_IDENTITY_SCHEMA='acs.opening-identity/1';
function auOpeningIdentityIssues(model,buildingId){
  const bid=buildingId||'bld_0', issues=[], seen=new Set();
  const reserved=new Set([bid,'site','__proto__','constructor','prototype']);
  _auAllRooms(model).forEach(([t,r])=>{
    reserved.add(String(r.id));reserved.add(r.space_id||_auSpaceKey(bid,t,r.id));
  });
  (model.levels||[]).forEach(lv=>{if(lv&&typeof lv==='object')
    reserved.add(lv.id||bid+'.flr_'+(lv.index===undefined?0:lv.index));});
  const marker=model._opening_identity;
  if(marker!==null&&marker!==undefined&&(!marker||typeof marker!=='object'||Array.isArray(marker)||
      marker.schema!==AU_OPENING_IDENTITY_SCHEMA||!Number.isInteger(marker.next)||
      marker.next<0||marker.next>=2147483647))
    issues.push(_auIssue('MODEL_INTEGRITY_FAILURE','_opening_identity',
      'unsupported opening identity version or allocator'));
  _auAllRooms(model).forEach(([t,room])=>{
    const sid=room.space_id||_auSpaceKey(bid,t,room.id);
    ['doors','windows'].forEach(key=>(room[key]||[]).forEach((op,i)=>{
      const legacy=sid+'.'+key.slice(0,-1)+'_'+i;
      if(!op||typeof op!=='object'||Array.isArray(op)){
        issues.push(_auIssue('MODEL_INTEGRITY_FAILURE',legacy,'an opening record is not an object'));return;}
      const oid=Object.prototype.hasOwnProperty.call(op,'id')?op.id:
        (marker===null||marker===undefined?legacy:null);
      if(typeof oid!=='string'||!oid||oid.length>256||/[@\s\x00-\x1f\x7f-\x9f\ufeff<>"'\\]/.test(oid)||
          AU_DERIVED_NS.some(ns=>oid.startsWith(ns))){
        issues.push(_auIssue('MODEL_INTEGRITY_FAILURE',legacy,'opening identity is missing or invalid'));return;}
      if(seen.has(oid)||reserved.has(oid)) issues.push(_auIssue('ID_COLLISION',oid,'duplicate opening identity'));
      seen.add(oid);
    }));
  });
  return issues;
}
function auStabiliseOpeningIds(model,buildingId){
  const bid=buildingId||'bld_0';
  if(auOpeningIdentityIssues(model,bid).length) throw new Error('invalid opening identity contract');
  if(model._opening_identity!==null&&model._opening_identity!==undefined) return [];
  const changed=[];
  _auAllRooms(model).forEach(([t,room])=>{
    const sid=room.space_id||_auSpaceKey(bid,t,room.id);
    ['doors','windows'].forEach(key=>(room[key]||[]).forEach((op,i)=>{
      if(!Object.prototype.hasOwnProperty.call(op,'id')){
        op.id=sid+'.'+key.slice(0,-1)+'_'+i;
        changed.push('floors.'+t+'.rooms.'+room.id+'.'+key+'['+i+'].id');
      }
    }));
  });
  model._opening_identity={schema:AU_OPENING_IDENTITY_SCHEMA,next:0};
  return changed.concat(['_opening_identity']);
}
function _auNewOpeningId(model,cmd){
  const state=model._opening_identity;
  let serial=state.next;
  const base=auModelHash(model), existing=new Set();
  _auAllRooms(model).forEach(([,r])=>['doors','windows'].forEach(k=>
    (r[k]||[]).forEach(o=>existing.add(o.id))));
  let oid='opening_'+_auSha16({command:cmd.command_hash,serial:serial,base:base});
  while(existing.has(oid)){
    serial++;
    oid='opening_'+_auSha16({command:cmd.command_hash,serial:serial,base:base});
  }
  state.next=serial+1;
  return oid;
}

function _auOpeningReference(model,t,rid,key,i){
  const op=_auFindRoom(model,t,rid)[key][i];
  return op.id||t+'.'+rid+'.'+key.slice(0,-1)+'_'+i;
}
function auResolveTarget(model,targetId,buildingId){
  const bid=buildingId||'bld_0';
  const tid=(typeof targetId==='string'&&targetId)?targetId:null;
  if(tid===null) return {kind:null,issues:[_auIssue('INVALID_TARGET',targetId,
    'target must be a non-empty string')]};
  for(let i=0;i<AU_DERIVED_NS.length;i++){ const ns=AU_DERIVED_NS[i];
    if(tid.indexOf(ns)===0) return {kind:null,issues:[_auIssue('INVALID_TARGET',tid,
      'this identifier names a derived projection ('+ns+'), not a semantic source; '+
      'edit the element it was derived from instead')]}; }
  const body=tid.split('@')[0], parts=body.split('.');
  const openingHits=[];
  _auAllRooms(model).forEach(([t,room])=>['doors','windows'].forEach(key=>
    (room[key]||[]).forEach((op,i)=>{
      if(op&&op.id===body) openingHits.push({kind:key==='doors'?'DOOR':'WINDOW',
        template:t,room_id:room.id,opening_index:i,opening_key:key,issues:[]});
    })));
  if(openingHits.length>1) return {kind:null,issues:[_auIssue('AMBIGUOUS_TARGET',tid,
    'duplicate opening identity')]};
  if(openingHits.length){
    if(tid.includes('@')&&!(model.levels||[]).some(lv=>String(lv.index)===tid.slice(tid.indexOf('@')+1)&&
        lv.template===openingHits[0].template))
      return {kind:null,issues:[_auIssue('INVALID_TARGET',tid,'opening instance level does not exist')]};
    return openingHits[0];
  }
  const last=parts[parts.length-1];
  if(parts.length>=4&&(last.indexOf('door_')===0||last.indexOf('window_')===0)){
    const kind=(last.indexOf('door_')===0)?'DOOR':'WINDOW';
    const template=parts[1], roomId=parts.slice(2,parts.length-1).join('.');
    const room=_auFindRoom(model,template,roomId);
    if(room===null) return {kind:null,issues:[_auIssue('INVALID_TARGET',tid,
      'the space behind this opening does not exist')]};
    const idx=last.split('_').pop();
    if(!/^\d+$/.test(idx)) return {kind:null,issues:[_auIssue('INVALID_TARGET',tid,
      'opening index is not a number')]};
    const i=parseInt(idx,10);
    const key=(kind==='DOOR')?'doors':'windows';
    const lst=room[key]||[];
    if(i<0||i>=lst.length) return {kind:null,issues:[_auIssue('INVALID_TARGET',tid,
      'opening index is out of range')]};
    if(model._opening_identity!==null&&model._opening_identity!==undefined||
       Object.prototype.hasOwnProperty.call(lst[i],'id'))
      return {kind:null,issues:[_auIssue('INVALID_TARGET',tid,'opening identity no longer exists')]};
    return {kind:kind,template:template,room_id:roomId,opening_index:i,
      opening_key:key,issues:[]}; }
  if(parts.length>=3&&last.indexOf('wall_')===0)
    return {kind:'WALL',wall_id:tid,issues:[]};
  if(parts.length>=3){
    const template=parts[1], roomId=parts.slice(2).join('.');
    if(_auFindRoom(model,template,roomId)!==null)
      return {kind:'SPACE',template:template,room_id:roomId,issues:[]}; }
  if(parts.length===2&&_auFindRoom(model,parts[0],parts[1])!==null)
    return {kind:'SPACE',template:parts[0],room_id:parts[1],issues:[]};
  const hits=_auAllRooms(model).filter(p=>String(p[1].id)===tid);
  if(hits.length===1)
    return {kind:'SPACE',template:hits[0][0],room_id:tid,issues:[]};
  if(hits.length>1)
    return {kind:null,candidates:hits.map(p=>_auSpaceKey(bid,p[0],tid)),
      issues:[_auIssue('AMBIGUOUS_TARGET',tid,
        'the same space id exists on more than one level template')]};
  const levels=model.levels||[];
  for(let i=0;i<levels.length;i++){ const lv=levels[i];
    if(tid===String(lv.template)||tid===String(lv.name)||tid===(bid+'.flr_'+lv.index))
      return {kind:'LEVEL',level_index:lv.index,template:lv.template,issues:[]}; }
  if(tid==='site'||tid==='SITE') return {kind:'SITE',issues:[]};
  if(tid==='building'||tid==='BUILDING'||tid===bid) return {kind:'BUILDING',issues:[]};
  if(parts.length>=3&&last.indexOf('obj_')===0){
    /* يُقبَل الشكلان: <template>.<room>.obj_<n> و <bid>.<template>.<room>.obj_<n> */
    let template, roomId;
    if(parts.length>=4){ template=parts[1]; roomId=parts.slice(2,parts.length-1).join('.'); }
    else { template=parts[0]; roomId=parts[1]; }
    let room=_auFindRoom(model,template,roomId);
    if(room===null&&parts.length>=4){
      template=parts[0]; roomId=parts.slice(1,parts.length-1).join('.');
      room=_auFindRoom(model,template,roomId); }
    if(room!==null){
      const i=parseInt(last.split('_').pop(),10);
      const objs=room.objects||[];
      if(i>=0&&i<objs.length)
        return {kind:'OBJECT',template:template,room_id:roomId,object_index:i,issues:[]}; }
    return {kind:null,issues:[_auIssue('INVALID_TARGET',tid,
      'the object behind this id does not exist')]}; }
  if(parts.length>=3&&last.indexOf('point_')===0){
    /* نقطة دلالية داخل غرفة: <template>.<room>.point_<n> */
    let template, roomId;
    if(parts.length>=4){ template=parts[1]; roomId=parts.slice(2,parts.length-1).join('.'); }
    else { template=parts[0]; roomId=parts[1]; }
    let room=_auFindRoom(model,template,roomId);
    if(room===null&&parts.length>=4){
      template=parts[0]; roomId=parts.slice(1,parts.length-1).join('.');
      room=_auFindRoom(model,template,roomId); }
    if(room!==null){
      const i=parseInt(last.split('_').pop(),10);
      const pts=room.points||[];
      if(i>=0&&i<pts.length)
        return {kind:'POINT',template:template,room_id:roomId,point_index:i,issues:[]}; }
    return {kind:null,issues:[_auIssue('INVALID_TARGET',tid,
      'the point behind this id does not exist')]}; }
  return {kind:null,issues:[_auIssue('INVALID_TARGET',tid,
    'target does not resolve in the canonical model')]}; }

/* ------------------------------------------------- الجدران المشتقّة ---- */
function _auDerivedArch(model,buildingId){
  try{ return compileArchitecture(_auCopy(model),buildingId||'bld_0',null,0); }
  catch(e){ return null; } }
function _auWallSourceEdges(model,arch,wallId){
  if(!arch) return [];
  let wall=null;
  (arch.walls||[]).forEach(w=>{ if(String(w.id)===String(wallId)) wall=w; });
  if(!wall) return [];
  const axis=wall.axis, fixed=_auNum(wall.fixed);
  const u0=_auNum(wall.u0), u1=_auNum(wall.u1), lvl=wall.level_index;
  if(axis===undefined||fixed===null||u0===null||u1===null) return [];
  let template=null;
  (model.levels||[]).forEach(l=>{ if(l.index===lvl) template=l.template; });
  if(template===null) return [];
  const out=[];
  _auRoomsOf(model,template).forEach(r=>{
    const rect=r.rect;
    if(!Array.isArray(rect)||rect.length!==4) return;
    const x=_auNum(rect[0]), z=_auNum(rect[1]), w=_auNum(rect[2]), d=_auNum(rect[3]);
    if(x===null||z===null||w===null||d===null) return;
    if(axis==='x'){
      const lo=Math.min(x,x+w), hi=Math.max(x,x+w);
      if(Math.abs(z-fixed)<1e-9&&lo-1e-9<=u0&&u1<=hi+1e-9) out.push([template,String(r.id),'N']);
      if(Math.abs((z+d)-fixed)<1e-9&&lo-1e-9<=u0&&u1<=hi+1e-9) out.push([template,String(r.id),'S']);
    } else {
      const lo=Math.min(z,z+d), hi=Math.max(z,z+d);
      if(Math.abs(x-fixed)<1e-9&&lo-1e-9<=u0&&u1<=hi+1e-9) out.push([template,String(r.id),'W']);
      if(Math.abs((x+w)-fixed)<1e-9&&lo-1e-9<=u0&&u1<=hi+1e-9) out.push([template,String(r.id),'E']); } });
  return out; }

/* ------------------------------------------------------------ الأمر ---- */
function auNormaliseCommand(command,baseRevision,snap,gridM){
  const issues=[];
  if(!command||typeof command!=='object'||Array.isArray(command))
    return _auResult([_auIssue('INVALID_COMMAND','command','command must be an object')],
      {command:null});
  let raw;
  try{ raw=JSON.stringify(command); }catch(e){ raw='{}'; }
  if(raw===undefined) raw='{}';
  if(raw.length>Number(AU_LIMITS.max_payload_bytes))
    return _auResult([_auIssue('PAYLOAD_REJECTED','command','payload is too large')],
      {command:null});
  issues.push.apply(issues,_auScan(command,0,'payload'));
  if(_auHasError(issues)) return _auResult(issues,{command:null});

  const ctype=_auEnum(command.type);
  if(AU_FORBIDDEN_TYPES.indexOf(ctype)>=0)
    return _auResult([_auIssue('COMMAND_NOT_ALLOWED',ctype,
      'there is no arbitrary or path-based write path')],{command:null});
  if(AU_COMMAND_TYPES.indexOf(ctype)<0)
    return _auResult([_auIssue('INVALID_COMMAND',command.type,
      'unknown authoring command type')],{command:null});
  if(AU_NOT_IMPLEMENTED.indexOf(ctype)>=0)
    return _auResult([_auIssue('COMMAND_NOT_IMPLEMENTED',ctype,
      'declared in the vocabulary but not authored in this phase')],{command:null});

  let source=_auEnum(command.source)||AU_DEFAULT_SOURCE;
  if(AU_SOURCES.indexOf(source)<0){
    issues.push(_auIssue('INVALID_COMMAND',command.source,'unknown command source'));
    source=AU_DEFAULT_SOURCE; }

  let target=command.target_id;
  if(target!==null&&target!==undefined&&typeof target!=='string'){
    issues.push(_auIssue('INVALID_TARGET',null,'target must be a string when supplied'));
    target=null; }
  if(target===undefined) target=null;

  let params=command.parameters;
  if(params===null||params===undefined) params={};
  if(typeof params!=='object'||Array.isArray(params)){
    issues.push(_auIssue('INVALID_PARAMETER','parameters','parameters must be an object'));
    params={}; }

  let snapMode=_auEnum(snap!==undefined&&snap!==null?snap:command.snap)||'NONE';
  if(AU_SNAP_TYPES.indexOf(snapMode)<0){
    issues.push(_auIssue('INVALID_PARAMETER',snap,'unknown snap type')); snapMode='NONE'; }
  else if(AU_IMPLEMENTED_SNAPS.indexOf(snapMode)<0){
    issues.push(_auIssue('INVALID_PARAMETER',snapMode,
      'this snap type is declared but not implemented in this phase')); snapMode='NONE'; }
  let grid=_auNum(gridM!==undefined&&gridM!==null?gridM:command.grid_m);
  if(grid===null||grid<=0) grid=AU_DEFAULT_GRID;

  const SNAPPABLE=['dx','dz','dy','delta_m','x','z','offset','w','d','width','height'];
  const norm={};
  Object.keys(params).sort(_scmp).forEach(k=>{
    const v=params[k];
    const n=_auNum(v);
    if(n!==null&&typeof v!=='boolean'){
      let val=n;
      if(snapMode==='GRID'&&SNAPPABLE.indexOf(k)>=0) val=_pyRound(val/grid,0)*grid;
      norm[k]=_auQ(val);
    } else if(typeof v==='string'){ norm[k]=v; }
    else { norm[k]=_auCopy(v); } });

  const cons=command.constraints;
  const ncons={};
  if(cons!==null&&cons!==undefined){
    if(typeof cons!=='object'||Array.isArray(cons))
      issues.push(_auIssue('INVALID_PARAMETER','constraints','constraints must be an object'));
    else Object.keys(cons).sort(_scmp).forEach(k=>{
      if(AU_CONSTRAINT_KEYS.indexOf(k)<0){
        issues.push(_auIssue('INVALID_PARAMETER',k,'unknown constraint key')); return; }
      const v=cons[k];
      if(k==='must_preserve'||k==='must_not_change'||k==='allowed_scope'){
        if(!Array.isArray(v)){
          issues.push(_auIssue('INVALID_PARAMETER',k,'constraint must be a list')); return; }
        if(v.length>Number(AU_LIMITS.max_constraint_entries)){
          issues.push(_auIssue('INVALID_PARAMETER',k,'too many entries')); return; }
        const vals=[];
        v.forEach(x=>{
          const e=_auEnum(x);
          if(e===null){ issues.push(_auIssue('INVALID_PARAMETER',k,
            'constraint entries must be strings')); return; }
          if(k==='must_not_change'&&AU_MUST_NOT_CHANGE.indexOf(e)<0){
            issues.push(_auIssue('INVALID_PARAMETER',e,'unknown must_not_change subject')); return; }
          if(k==='must_preserve'&&AU_MUST_PRESERVE.indexOf(e)<0){
            issues.push(_auIssue('INVALID_PARAMETER',e,'unknown must_preserve subject')); return; }
          if(k==='allowed_scope'&&AU_DISCIPLINES.indexOf(e)<0){
            issues.push(_auIssue('INVALID_PARAMETER',e,'unknown scope')); return; }
          vals.push(e); });
        ncons[k]=Array.from(new Set(vals)).sort(_scmp);
      } else {
        const n=_auNum(v);
        if(n===null||n<0){ issues.push(_auIssue('INVALID_PARAMETER',k,
          'max_delta_m must be a finite non-negative number')); return; }
        ncons[k]=_auQ(n); } }); }

  const br=(baseRevision!==undefined&&baseRevision!==null)?baseRevision
    :((command.base_revision===undefined)?null:command.base_revision);
  const identity={type:ctype,target_id:target,parameters:norm,
    constraints:ncons,base_revision:br};
  const chash=_auSha16(identity);
  const out={command_id:'cmd:'+chash,command_hash:chash,type:ctype,
    discipline:(AU_COMMAND_DISCIPLINE[ctype]===undefined)?null:AU_COMMAND_DISCIPLINE[ctype],
    target_id:target,parameters:norm,constraints:ncons,source:source,
    actor_id:(typeof command.actor_id==='string')?command.actor_id:null,
    base_revision:br,
    created_at:(typeof command.created_at==='string')?command.created_at:null,
    status:'NORMALISED',snap:snapMode,grid_m:_auQ(grid),writes_to_model:false,
    note:'a normalised authoring command; identity excludes created_at, actor and source '+
         'so the same semantic edit always hashes the same'};
  return _auResult(issues,{command:out}); }

function auCommandHash(command,baseRevision){
  const r=auNormaliseCommand(command,baseRevision,null,null);
  return r.command?r.command.command_hash:null; }

/* ------------------------------------------------------ تطبيق الأوامر -- */
function _auNewId(kind,parent,chash,existing){
  const base=kind+'_'+_auSha16({kind:kind,parent:parent,cmd:chash}).slice(0,8);
  if(existing.indexOf(base)<0) return base;
  let n=2;
  while(existing.indexOf(base+'_'+n)>=0) n++;
  return base+'_'+n; }

function _auApply(model,cmd,buildingId){
  const bid=buildingId||'bld_0';
  const issues=[]; let changed=[], dep=[], brk=[];
  const candidate=_auCopy(model);
  const ctype=cmd.type, params=cmd.parameters, target=cmd.target_id;
  let identityPaths=[];
  const fail=()=>_auResult(issues,{candidate:null,changed_paths:[],dependencies:[],
    dependency_breaking:[]});
  const bad=(code,subj,detail)=>{ issues.push(_auIssue(code,subj,detail)); return fail(); };
  const needNum=(key,mn,mx)=>{
    const v=_auNum(params[key]);
    if(v===null){ issues.push(_auIssue('INVALID_PARAMETER',key,
      'a finite number is required')); return null; }
    if(Math.abs(v)>AU_MAX_COORD){ issues.push(_auIssue('COORDINATE_OUT_OF_BOUNDS',key,
      'value is outside the declared safe coordinate bound')); return null; }
    if(mn!==undefined&&mn!==null&&v<mn){ issues.push(_auIssue('INVALID_PARAMETER',key,
      'value is below the declared minimum')); return null; }
    if(mx!==undefined&&mx!==null&&v>mx){ issues.push(_auIssue('INVALID_PARAMETER',key,
      'value is above the declared maximum')); return null; }
    return v; };

  if(['ADD_DOOR','ADD_WINDOW','DELETE_DOOR','DELETE_WINDOW','MOVE_DOOR','MOVE_WINDOW',
      'CHANGE_DOOR_PROPERTIES','CHANGE_WINDOW_PROPERTIES'].includes(ctype)){
    const invalid=auOpeningIdentityIssues(candidate,bid);
    if(invalid.length) return _auResult(invalid,{candidate:null,changed_paths:[],
      dependencies:[],dependency_breaking:[]});
    identityPaths=auStabiliseOpeningIds(candidate,bid);
  }
  const locks=candidate._authoring_locks||{};
  const lockTarget=typeof target==='string'?target.split('@')[0]:target;
  if(ctype!=='LOCK_ELEMENT'&&ctype!=='UNLOCK_ELEMENT'&&target
     &&(Object.prototype.hasOwnProperty.call(locks,target)||Object.prototype.hasOwnProperty.call(locks,lockTarget)))
    return bad('TARGET_LOCKED',target,'the element is locked ('+(locks[target]||locks[lockTarget]).reason+')');

  if(ctype==='CHANGE_SITE_DIMENSIONS'){
    const w=needNum('w',AU_MIN_DIM,AU_MAX_DIM), d=needNum('d',AU_MIN_DIM,AU_MAX_DIM);
    if(w===null||d===null) return fail();
    if(!candidate.site) candidate.site={};
    candidate.site.w=_auQ(w); candidate.site.d=_auQ(d);
    changed=['site.w','site.d'];
  } else if(ctype==='CHANGE_BUILDING_POSITION'){
    const x=needNum('x'), z=needNum('z');
    if(x===null||z===null) return fail();
    if(!candidate.placement) candidate.placement={};
    candidate.placement.position={x:_auQ(x),z:_auQ(z)};
    changed=['placement.position'];
  } else if(ctype==='CHANGE_BUILDING_ROTATION'){
    const r=needNum('rotation_deg');
    if(r===null) return fail();
    if(!candidate.placement) candidate.placement={};
    candidate.placement.rotation_deg=_auQ(((r%360)+360)%360);
    changed=['placement.rotation_deg'];
  } else if(ctype==='CHANGE_LEVEL_HEIGHT'){
    const h=needNum('height_m',Number(AU_LIMITS.min_level_height_m),
      Number(AU_LIMITS.max_level_height_m));
    if(h===null) return fail();
    candidate.floor_height=_auQ(h);
    changed=['floor_height'];
  } else if(ctype==='ADD_LEVEL'){
    const levels=candidate.levels||[];
    if(levels.length>=Number(AU_LIMITS.max_level_count))
      return bad('INVALID_PARAMETER','levels','the declared level cap is reached');
    const template=params.template;
    if(typeof template!=='string'||!template)
      return bad('INVALID_PARAMETER','template','a template name is required');
    if(!Object.prototype.hasOwnProperty.call(_auTemplates(candidate),template))
      return bad('INVALID_TARGET',template,
        'no floor plate exists for this template; add its spaces first');
    let mx=-1; levels.forEach(l=>{ const i=parseInt(l.index||0,10); if(i>mx) mx=i; });
    const idx=mx+1;
    const name=(typeof params.name==='string')?params.name:('level_'+idx);
    if(levels.some(l=>parseInt(l.index||0,10)===idx))
      return bad('ID_COLLISION',String(idx),'a level with this index already exists');
    candidate.levels=levels.concat([{index:idx,name:name,template:template}]);
    changed=['levels['+idx+']'];
  } else if(ctype==='DELETE_LEVEL'){
    const res=auResolveTarget(candidate,target,bid);
    if(res.kind!=='LEVEL'){
      issues.push.apply(issues,(res.issues&&res.issues.length)?res.issues
        :[_auIssue('INVALID_TARGET',target,'not a level')]);
      return fail(); }
    const levels=candidate.levels||[];
    if(levels.length<=1)
      return bad('DEPENDENCY_CONFLICT',target,'the last remaining level cannot be deleted');
    const tmpl=res.template, rooms=_auRoomsOf(candidate,tmpl);
    const others=levels.filter(l=>l.template===tmpl&&l.index!==res.level_index);
    if(rooms.length&&!others.length)
      return bad('LEVEL_NOT_EMPTY',target,'the level still carries '+rooms.length+
        ' spaces; delete or move them first');
    candidate.levels=levels.filter(l=>l.index!==res.level_index);
    brk=[bid+'.flr_'+res.level_index];
    changed=['levels'];
  } else if(ctype==='RESIZE_SPACE'||ctype==='RENAME_SPACE'||ctype==='DELETE_SPACE'){
    const res=auResolveTarget(candidate,target,bid);
    if(res.kind!=='SPACE'){
      issues.push.apply(issues,(res.issues&&res.issues.length)?res.issues
        :[_auIssue('INVALID_TARGET',target,'not a space')]);
      return _auResult(issues,{candidate:null,changed_paths:[],
        dependencies:res.candidates||[],dependency_breaking:[]}); }
    const t=res.template, rid=res.room_id, room=_auFindRoom(candidate,t,rid);
    if(ctype==='RENAME_SPACE'){
      const nn=params.name;
      if(typeof nn!=='string'||!nn)
        return bad('INVALID_PARAMETER','name','a non-empty name is required');
      room.name=nn;
      changed=['floors.'+t+'.rooms.'+rid+'.name'];
    } else if(ctype==='RESIZE_SPACE'){
      const rect=room.rect;
      if(!Array.isArray(rect)||rect.length!==4)
        return bad('MODEL_INTEGRITY_FAILURE',target,'the space carries no rectangle to resize');
      const x=_auNum(rect[0]), z=_auNum(rect[1]), w=_auNum(rect[2]), d=_auNum(rect[3]);
      let nw=_auNum(params.w), nd=_auNum(params.d), nx=_auNum(params.x), nz=_auNum(params.z);
      nw=(nw===null)?w:nw; nd=(nd===null)?d:nd; nx=(nx===null)?x:nx; nz=(nz===null)?z:nz;
      const pairs=[['w',nw],['d',nd]];
      for(let i=0;i<pairs.length;i++){ const v=pairs[i][1];
        if(v===null||v<AU_MIN_DIM||v>AU_MAX_DIM)
          return bad('INVALID_PARAMETER',pairs[i][0],
            'a space side must be a finite value within the declared bounds'); }
      const cps=[['x',nx],['z',nz]];
      for(let i=0;i<cps.length;i++) if(!_auCoordOk(cps[i][1]))
        return bad('COORDINATE_OUT_OF_BOUNDS',cps[i][0],
          'value is outside the declared safe coordinate bound');
      const oldW=w, oldD=d;
      room.rect=[_auQ(nx),_auQ(nz),_auQ(nw),_auQ(nd)];
      changed=['floors.'+t+'.rooms.'+rid+'.rect'];
      ['doors','windows'].forEach(key=>{
        (room[key]||[]).forEach((op,i)=>{
          const edge=String(op.edge||'N').toUpperCase().slice(0,1);
          const span=(edge==='N'||edge==='S')?nw:nd;
          const off=_auNum(op.offset), wid=_auNum(op.width)||0;
          if(off!==null&&(off-wid/2<-1e-9||off+wid/2>span+1e-9))
            issues.push(_auIssue('OPENING_OUT_OF_RANGE',
              _auOpeningReference(candidate,t,rid,key,i),
              'the opening no longer fits the resized edge')); }); });
      dep=[t+'.'+rid];
      if(oldW!==nw||oldD!==nd) dep.push('space_boundary_changed');
    } else {
      const rooms=_auRoomsOf(candidate,t);
      const deps=[];
      ['doors','windows'].forEach(key=>{ (room[key]||[]).forEach((op,i)=>{
        deps.push(_auOpeningReference(candidate,t,rid,key,i)); }); });
      (room.objects||[]).forEach((o,i)=>{ deps.push(t+'.'+rid+'.obj_'+i); });
      dep=deps; brk=deps.concat([t+'.'+rid]);
      candidate.floors[t].rooms=rooms.filter(r=>String(r.id)!==rid);
      changed=['floors.'+t+'.rooms']; }
  } else if(ctype==='ADD_SPACE'){
    const t=params.template;
    if(typeof t!=='string'||!Object.prototype.hasOwnProperty.call(_auTemplates(candidate),t))
      return bad('INVALID_TARGET',t,'unknown floor template');
    const rect=params.rect;
    if(!Array.isArray(rect)||rect.length!==4)
      return bad('INVALID_PARAMETER','rect','a rectangle of four finite numbers is required');
    const vals=rect.map(_auNum);
    if(vals.some(v=>v===null))
      return bad('INVALID_PARAMETER','rect','a rectangle carries a non-finite value');
    if(vals.some(v=>Math.abs(v)>AU_MAX_COORD))
      return bad('COORDINATE_OUT_OF_BOUNDS','rect',
        'value is outside the declared safe coordinate bound');
    if(vals[2]<AU_MIN_DIM||vals[3]<AU_MIN_DIM||vals[2]>AU_MAX_DIM||vals[3]>AU_MAX_DIM)
      return bad('INVALID_PARAMETER','rect','space sides are outside the declared bounds');
    const rooms=_auRoomsOf(candidate,t);
    if(rooms.length>=Number(AU_LIMITS.max_spaces_per_level))
      return bad('INVALID_PARAMETER','rooms','the declared space cap is reached');
    let rid=params.id;
    if(typeof rid!=='string'||!rid)
      rid=_auNewId('space',t,cmd.command_hash,rooms.map(r=>String(r.id)));
    if(rooms.some(r=>String(r.id)===rid))
      return bad('ID_COLLISION',rid,'a space with this id already exists on this template');
    const nr={id:rid,rect:vals.map(_auQ)};
    if(typeof params.name==='string') nr.name=params.name;
    candidate.floors[t].rooms=rooms.concat([nr]);
    changed=['floors.'+t+'.rooms.'+rid];
  } else if(ctype==='MOVE_DOOR'||ctype==='MOVE_WINDOW'||ctype==='DELETE_DOOR'
            ||ctype==='DELETE_WINDOW'||ctype==='CHANGE_DOOR_PROPERTIES'
            ||ctype==='CHANGE_WINDOW_PROPERTIES'){
    const want=(ctype.indexOf('DOOR')>=0)?'DOOR':'WINDOW';
    const res=auResolveTarget(candidate,target,bid);
    if(res.kind!==want){
      issues.push.apply(issues,(res.issues&&res.issues.length)?res.issues
        :[_auIssue('INVALID_TARGET',target,'target is not a '+want.toLowerCase())]);
      return fail(); }
    const t=res.template, rid=res.room_id, i=res.opening_index, key=res.opening_key;
    const room=_auFindRoom(candidate,t,rid), op=room[key][i];
    const rect=(room.rect||[0,0,0,0]).map(_auNum);
    if(ctype.indexOf('DELETE')===0){
      dep=[_auOpeningReference(candidate,t,rid,key,i)]; brk=dep.slice();
      room[key]=room[key].filter((o,j)=>j!==i);
      changed=['floors.'+t+'.rooms.'+rid+'.'+key];
    } else if(ctype.indexOf('MOVE')===0){
      const edge=(params.edge===undefined||params.edge===null)
        ?_auEdge(op.edge||'N'):_auEdge(params.edge);
      if(edge===null)
        return bad('INVALID_PARAMETER',params.edge,
          'edge must be exactly one of N, S, E or W');
      const off=_auNum(params.offset);
      if(off===null) return bad('INVALID_PARAMETER','offset','a finite offset is required');
      if(!_auCoordOk(off)) return bad('COORDINATE_OUT_OF_BOUNDS','offset',
        'value is outside the declared safe coordinate bound');
      const span=(edge==='N'||edge==='S')?rect[2]:rect[3];
      const wid=_auNum(op.width)||0;
      if(off-wid/2<-1e-9||off+wid/2>span+1e-9)
        return bad('OPENING_OUT_OF_RANGE',target,
          'the opening would extend past its host edge (edge span '+span.toFixed(3)+
          ' m, requested centre '+off.toFixed(3)+' m, width '+wid.toFixed(3)+' m)');
      op.edge=edge; op.offset=_auQ(off);
      changed=['floors.'+t+'.rooms.'+rid+'.'+key+'['+i+']'];
    } else {
      const allowed=(want==='WINDOW')?['width','height','sill']:['width','height'];
      let touched=false;
      for(let a=0;a<allowed.length;a++){ const k=allowed[a];
        if(Object.prototype.hasOwnProperty.call(params,k)){
          const v=_auNum(params[k]);
          if(v===null||v<AU_MIN_DIM||v>AU_MAX_DIM)
            return bad('INVALID_PARAMETER',k,
              'a finite dimension within the declared bounds is required');
          if(k==='width'){
            const edge=String(op.edge||'N').toUpperCase().slice(0,1);
            const span=(edge==='N'||edge==='S')?rect[2]:rect[3];
            const off=_auNum(op.offset)||0;
            if(off-v/2<-1e-9||off+v/2>span+1e-9)
              return bad('OPENING_OUT_OF_RANGE',target,
                'the widened opening would extend past its host edge'); }
          op[k]=_auQ(v); touched=true; } }
      if(!touched) return bad('INVALID_PARAMETER','parameters',
        'no editable opening property was supplied');
      changed=['floors.'+t+'.rooms.'+rid+'.'+key+'['+i+']']; }
  } else if(ctype==='ADD_DOOR'||ctype==='ADD_WINDOW'){
    const key=(ctype==='ADD_DOOR')?'doors':'windows';
    const res=auResolveTarget(candidate,target,bid);
    if(res.kind!=='SPACE'){
      issues.push.apply(issues,(res.issues&&res.issues.length)?res.issues
        :[_auIssue('HOST_INVALID',target,'an opening must be added to a space')]);
      return _auResult(issues,{candidate:null,changed_paths:[],
        dependencies:res.candidates||[],dependency_breaking:[]}); }
    const t=res.template, rid=res.room_id, room=_auFindRoom(candidate,t,rid);
    const rect=(room.rect||[0,0,0,0]).map(_auNum);
    const edge=_auEdge(params.edge);
    if(edge===null)
      return bad('INVALID_PARAMETER',params.edge,
        'edge must be exactly one of N, S, E or W');
    const off=_auNum(params.offset), wid=_auNum(params.width);
    if(off===null||wid===null)
      return bad('INVALID_PARAMETER','offset/width','a finite offset and width are required');
    if(wid<AU_MIN_DIM||wid>AU_MAX_DIM)
      return bad('INVALID_PARAMETER','width','width is outside the declared bounds');
    const span=(edge==='N'||edge==='S')?rect[2]:rect[3];
    if(off-wid/2<-1e-9||off+wid/2>span+1e-9)
      return bad('OPENING_OUT_OF_RANGE',target,
        'the opening would extend past its host edge');
    const nn={edge:edge,offset:_auQ(off),width:_auQ(wid)};
    nn.id=_auNewOpeningId(candidate,cmd);
    identityPaths.push('_opening_identity');
    ['height','sill'].forEach(k=>{ const v=_auNum(params[k]); if(v!==null) nn[k]=_auQ(v); });
    if(!room[key]) room[key]=[];
    room[key]=room[key].concat([nn]);
    changed=['floors.'+t+'.rooms.'+rid+'.'+key+'['+(room[key].length-1)+']'];
  } else if(ctype==='MOVE_WALL'){
    const arch=_auDerivedArch(candidate,bid);
    const edges=_auWallSourceEdges(candidate,arch,target);
    if(!edges.length)
      return bad('INVALID_TARGET',target,
        'the wall does not resolve to any space edge in the canonical model');
    const delta=_auNum(params.delta_m);
    if(delta===null) return bad('INVALID_PARAMETER','delta_m','a finite delta is required');
    if(!_auCoordOk(delta)) return bad('COORDINATE_OUT_OF_BOUNDS','delta_m',
      'value is outside the declared safe coordinate bound');
    const strategy=_auEnum(params.hosted_strategy);
    const hosted=[];
    edges.forEach(e=>{ const room=_auFindRoom(candidate,e[0],e[1]);
      ['doors','windows'].forEach(key=>{ (room[key]||[]).forEach((op,i)=>{
        if(String(op.edge||'N').toUpperCase().slice(0,1)===e[2])
          hosted.push([e[0],e[1],key,i,e[2]]); }); }); });
    if(hosted.length){
      if(strategy===null)
        return bad('HOSTED_STRATEGY_REQUIRED',target,hosted.length+
          ' hosted openings ride this wall; state a hosted strategy instead of letting '+
          'the engine choose');
      if(AU_HOSTED_STRATEGIES.indexOf(strategy)<0)
        return bad('INVALID_PARAMETER',strategy,'unknown hosted element strategy');
      if(strategy==='CANCEL_IF_HOSTED'){
        dep=hosted.map(h=>_auOpeningReference(candidate,h[0],h[1],h[2],h[3]));
        return bad('DEPENDENCY_CONFLICT',target,'the wall carries '+hosted.length+
          ' hosted openings and the chosen strategy is to cancel rather than move them'); } }
    for(let e=0;e<edges.length;e++){
      const t=edges[e][0], rid=edges[e][1], edge=edges[e][2];
      const room=_auFindRoom(candidate,t,rid);
      const rect=(room.rect||[0,0,0,0]).map(_auNum);
      let x=rect[0], z=rect[1], w=rect[2], d=rect[3];
      if(edge==='N'){ z=z+delta; d=d-delta; }
      else if(edge==='S'){ d=d+delta; }
      else if(edge==='W'){ x=x+delta; w=w-delta; }
      else { w=w+delta; }
      if(w<AU_MIN_DIM||d<AU_MIN_DIM)
        return bad('INVALID_PARAMETER','delta_m',
          'the move would collapse space '+rid+' below the minimum dimension');
      if(!(_auCoordOk(x)&&_auCoordOk(z)))
        return bad('COORDINATE_OUT_OF_BOUNDS','delta_m',
          'the move would place a space outside the declared bound');
      room.rect=[_auQ(x),_auQ(z),_auQ(w),_auQ(d)];
      changed.push('floors.'+t+'.rooms.'+rid+'.rect'); }
    if(hosted.length&&strategy==='KEEP_WORLD_POSITION'){
      for(let h=0;h<hosted.length;h++){
        const t=hosted[h][0], rid=hosted[h][1], key=hosted[h][2];
        const i=hosted[h][3], edge=hosted[h][4];
        const room=_auFindRoom(candidate,t,rid), op=room[key][i];
        const off=_auNum(op.offset);
        if(off===null) continue;
        const shift=(edge==='N'||edge==='W')?delta:0;
        const newOff=off-shift;
        const span=(edge==='N'||edge==='S')?_auNum(room.rect[2]):_auNum(room.rect[3]);
        const wid=_auNum(op.width)||0;
        if(newOff-wid/2<-1e-9||newOff+wid/2>span+1e-9)
          return bad('OPENING_OUT_OF_RANGE',_auOpeningReference(candidate,t,rid,key,i),
            'keeping the world position would push the opening past its host edge; '+
            'choose another strategy or a smaller move');
        op.offset=_auQ(newOff);
        changed.push('floors.'+t+'.rooms.'+rid+'.'+key+'['+i+']'); } }
    dep=hosted.map(h=>_auOpeningReference(candidate,h[0],h[1],h[2],h[3]));
    brk=dep.slice();
  } else if(ctype==='ADD_WALL'){
    return bad('COMMAND_NOT_ALLOWED','ADD_WALL',
      'walls are derived from space rectangles in this model; add or resize a space '+
      'instead of authoring a free-standing wall, so the derived geometry and the '+
      'semantic source cannot disagree');
  } else if(ctype==='DELETE_WALL'){
    const arch=_auDerivedArch(candidate,bid);
    const edges=_auWallSourceEdges(candidate,arch,target);
    if(!edges.length)
      return bad('INVALID_TARGET',target,
        'the wall does not resolve to any space edge in the canonical model');
    return bad('DEPENDENCY_CONFLICT',target,'this wall is generated by '+edges.length+
      ' space edge(s) and cannot be deleted on its own without orphaning them; '+
      'delete or resize the space instead');
  } else if(ctype==='MOVE_OBJECT'||ctype==='DELETE_OBJECT'
            ||ctype==='MOVE_STAIR'||ctype==='DELETE_STAIR'){
    const res=auResolveTarget(candidate,target,bid);
    if(res.kind!=='OBJECT'){
      issues.push.apply(issues,(res.issues&&res.issues.length)?res.issues
        :[_auIssue('INVALID_TARGET',target,'not an object')]);
      return fail(); }
    const t=res.template, rid=res.room_id, i=res.object_index;
    const room=_auFindRoom(candidate,t,rid), obj=(room.objects||[])[i];
    const kindStr=String(obj.kind||'').toLowerCase();
    const isStair=(kindStr==='stairs'||kindStr==='stair');
    if(ctype.slice(-5)==='STAIR'&&!isStair)
      return bad('INVALID_TARGET',target,'the target object is not a stair');
    if(ctype.slice(-6)==='OBJECT'&&isStair)
      return bad('AUTHORING_SCOPE_VIOLATION',target,
        'a stair carries vertical connectivity; use the stair commands so the downstream '+
        'effect is reported rather than hidden inside a generic move');
    if(ctype.indexOf('DELETE')===0){
      dep=[t+'.'+rid+'.obj_'+i].concat(isStair?['vertical_connectivity']:[]);
      brk=[t+'.'+rid+'.obj_'+i];
      room.objects=room.objects.filter((o,j)=>j!==i);
      changed=['floors.'+t+'.rooms.'+rid+'.objects'];
    } else {
      const x=needNum('x'), z=needNum('z');
      if(x===null||z===null) return fail();
      obj.x=_auQ(x); obj.z=_auQ(z);
      changed=['floors.'+t+'.rooms.'+rid+'.objects['+i+']'];
      dep=isStair?['vertical_connectivity']:[]; }
  } else if(ctype==='MOVE_POINT'||ctype==='DELETE_POINT'
            ||ctype==='CHANGE_POINT_PROPERTIES'){
    /* نقطة المرحلة الأولى مصدر معماري دلالي (مثل objects) تُشتقّ منه الميكانيكا
       والحريق. تُحرَّر هنا ليمرّ الاقتراح الهندسي المعتمد بمسار الإيداع الواحد. */
    const res=auResolveTarget(candidate,target,bid);
    if(res.kind!=='POINT'){
      issues.push.apply(issues,(res.issues&&res.issues.length)?res.issues
        :[_auIssue('INVALID_TARGET',target,'not a point')]);
      return fail(); }
    const t=res.template, rid=res.room_id, i=res.point_index;
    const room=_auFindRoom(candidate,t,rid), pt=(room.points||[])[i];
    if(ctype==='DELETE_POINT'){
      dep=[t+'.'+rid+'.point_'+i]; brk=[t+'.'+rid+'.point_'+i];
      room.points=room.points.filter((o,j)=>j!==i);
      changed=['floors.'+t+'.rooms.'+rid+'.points'];
    } else if(ctype==='MOVE_POINT'){
      const x=needNum('x'), z=needNum('z');
      if(x===null||z===null) return fail();
      const rect=(room.rect||[0,0,0,0]).map(_auNum);
      if(x<-1e-9||z<-1e-9||x>(rect[2]||0)+1e-9||z>(rect[3]||0)+1e-9)
        return bad('COORDINATE_OUT_OF_BOUNDS',target,
          'a point is addressed in space-local coordinates and must stay inside '+
          'its host rectangle');
      pt.x=_auQ(x); pt.z=_auQ(z);
      changed=['floors.'+t+'.rooms.'+rid+'.points['+i+']'];
    } else {
      let touched=false;
      if(Object.prototype.hasOwnProperty.call(params,'height')){
        const v=_auNum(params.height);
        if(v===null||v<0||v>AU_MAX_DIM)
          return bad('INVALID_PARAMETER','height',
            'a finite height within the declared bounds is required');
        pt.height=_auQ(v); touched=true; }
      if(Object.prototype.hasOwnProperty.call(params,'point_type')){
        const pv=_auEnum(params.point_type);
        if(!pv) return bad('INVALID_PARAMETER','point_type',
          'a semantic point type is required');
        pt.type=pv.toLowerCase(); touched=true; }
      if(!touched) return bad('INVALID_PARAMETER','parameters',
        'no editable point property was supplied');
      changed=['floors.'+t+'.rooms.'+rid+'.points['+i+']']; }
  } else if(ctype==='ADD_POINT'){
    const res=auResolveTarget(candidate,target,bid);
    if(res.kind!=='SPACE'){
      issues.push.apply(issues,(res.issues&&res.issues.length)?res.issues
        :[_auIssue('HOST_INVALID',target,'a point must be added to a space')]);
      return _auResult(issues,{candidate:null,changed_paths:[],
        dependencies:res.candidates||[],dependency_breaking:[]}); }
    const t=res.template, rid=res.room_id, room=_auFindRoom(candidate,t,rid);
    const ptype=_auEnum(params.point_type);
    if(!ptype) return bad('INVALID_PARAMETER','point_type',
      'a semantic point type is required');
    const x=needNum('x'), z=needNum('z');
    if(x===null||z===null) return fail();
    const rect=(room.rect||[0,0,0,0]).map(_auNum);
    if(x<-1e-9||z<-1e-9||x>(rect[2]||0)+1e-9||z>(rect[3]||0)+1e-9)
      return bad('COORDINATE_OUT_OF_BOUNDS',target,
        'a point is addressed in space-local coordinates and must stay inside '+
        'its host rectangle');
    const pts=room.points||[];
    if(pts.length>=AU_LIMITS.max_spaces_per_level)
      return bad('INVALID_PARAMETER','points','the declared point cap is reached');
    const np={type:ptype.toLowerCase(),x:_auQ(x),z:_auQ(z)};
    const ph=_auNum(params.height);
    if(ph!==null){
      if(ph<0||ph>AU_MAX_DIM)
        return bad('INVALID_PARAMETER','height',
          'a finite height within the declared bounds is required');
      np.height=_auQ(ph); }
    room.points=pts.concat([np]);
    changed=['floors.'+t+'.rooms.'+rid+'.points['+(room.points.length-1)+']'];
  } else if(ctype==='ADD_OBJECT'||ctype==='ADD_STAIR'){
    const res=auResolveTarget(candidate,target,bid);
    if(res.kind!=='SPACE'){
      issues.push.apply(issues,(res.issues&&res.issues.length)?res.issues
        :[_auIssue('INVALID_TARGET',target,'an object must be added to a space')]);
      return _auResult(issues,{candidate:null,changed_paths:[],
        dependencies:res.candidates||[],dependency_breaking:[]}); }
    const t=res.template, rid=res.room_id, room=_auFindRoom(candidate,t,rid);
    let kind=(typeof params.kind==='string')?params.kind:null;
    if(ctype==='ADD_STAIR') kind='stairs';
    if(!kind) return bad('INVALID_PARAMETER','kind','a semantic object kind is required');
    const x=needNum('x'), z=needNum('z');
    if(x===null||z===null) return fail();
    const count=_auNum(params.count);
    const nn={kind:kind,x:_auQ(x),z:_auQ(z),
      count:(count!==null&&count>=1)?Math.trunc(count):1};
    if(!room.objects) room.objects=[];
    room.objects=room.objects.concat([nn]);
    changed=['floors.'+t+'.rooms.'+rid+'.objects['+(room.objects.length-1)+']'];
    dep=(ctype==='ADD_STAIR')?['vertical_connectivity']:[];
  } else if(ctype==='PROMOTE_VISUAL_OBJECT'){
    const res=auResolveTarget(candidate,params.space_id||'',bid);
    if(res.kind!=='SPACE')
      return bad('INVALID_TARGET',params.space_id,
        'promotion needs the space that will own the new semantic object');
    const kind=params.semantic_kind, prov=params.provenance;
    if(typeof kind!=='string'||!kind)
      return bad('INVALID_PARAMETER','semantic_kind',
        'a target semantic kind is required; promotion is never implicit');
    if(typeof prov!=='string'||!prov)
      return bad('INVALID_PARAMETER','provenance',
        'promotion must record where the object came from');
    const x=needNum('x'), z=needNum('z');
    if(x===null||z===null) return fail();
    const t=res.template, rid=res.room_id, room=_auFindRoom(candidate,t,rid);
    if(!room.objects) room.objects=[];
    room.objects=room.objects.concat([{kind:kind,x:_auQ(x),z:_auQ(z),count:1,
      promoted_from_visual:true,provenance:prov,source_visual_object_id:target}]);
    changed=['floors.'+t+'.rooms.'+rid+'.objects['+(room.objects.length-1)+']'];
  } else if(ctype==='LOCK_ELEMENT'||ctype==='UNLOCK_ELEMENT'){
    if(typeof target!=='string'||!target)
      return bad('INVALID_TARGET',target,'a target is required');
    const lk=Object.assign({},candidate._authoring_locks||{});
    if(ctype==='LOCK_ELEMENT'){
      let reason;
      if(params.reason===undefined||params.reason===null) reason='USER_LOCKED';
      else { reason=_auEnum(params.reason);
        if(reason===null) return bad('INVALID_PARAMETER','reason',
          'a lock reason must be a string'); }
      if(AU_LOCK_REASONS.indexOf(reason)<0)
        return bad('INVALID_PARAMETER',reason,'unknown lock reason');
      lk[target]={locked:true,reason:reason};
    } else {
      if(!Object.prototype.hasOwnProperty.call(lk,target))
        return bad('INVALID_TARGET',target,'the element is not locked');
      delete lk[target]; }
    candidate._authoring_locks=lk;
    changed=['_authoring_locks.'+target];
  } else {
    return bad('COMMAND_NOT_IMPLEMENTED',ctype,'no applier for this command type'); }

  return _auResult(issues,{candidate:candidate,
    changed_paths:Array.from(new Set(changed.concat(identityPaths))).sort(_scmp),
    dependencies:Array.from(new Set(dep)).sort(_scmp),
    dependency_breaking:Array.from(new Set(brk)).sort(_scmp)}); }

/* ------------------------------------------------------------ القيود --- */
function _auEnforceConstraints(cmd,before,after,buildingId){
  const issues=[], cons=cmd.constraints||{};
  const spaces=m=>{ const o={};
    _auAllRooms(m).forEach(p=>{o[p[0]+'.'+p[1].id]=_auCopy(p[1]);}); return o; };
  const sb=spaces(before), sa=spaces(after);
  const keys=Array.from(new Set(Object.keys(sb).concat(Object.keys(sa)))).sort(_scmp);
  (cons.must_not_change||[]).forEach(subject=>{
    if(subject==='SPACE_RECT'){
      keys.forEach(k=>{ if(JSON.stringify((sb[k]||{}).rect)!==JSON.stringify((sa[k]||{}).rect))
        issues.push(_auIssue('CONSTRAINT_VIOLATION',k,
          'must_not_change SPACE_RECT was violated')); });
    } else if(subject==='SPACE_AREA'){
      keys.forEach(k=>{
        const rb=(sb[k]||{}).rect||[0,0,0,0], ra=(sa[k]||{}).rect||[0,0,0,0];
        const ab=(_auNum(rb[2])||0)*(_auNum(rb[3])||0);
        const aa=(_auNum(ra[2])||0)*(_auNum(ra[3])||0);
        if(Math.abs(ab-aa)>1e-9) issues.push(_auIssue('CONSTRAINT_VIOLATION',k,
          'must_not_change SPACE_AREA was violated')); });
    } else if(subject==='SPACE_NAME'){
      keys.forEach(k=>{ if((sb[k]||{}).name!==(sa[k]||{}).name)
        issues.push(_auIssue('CONSTRAINT_VIOLATION',k,
          'must_not_change SPACE_NAME was violated')); });
    } else if(subject==='LEVEL_HEIGHT'){
      if(before.floor_height!==after.floor_height)
        issues.push(_auIssue('CONSTRAINT_VIOLATION','floor_height',
          'must_not_change LEVEL_HEIGHT was violated'));
    } else if(subject==='SITE'){
      if(_auCanon(before.site===undefined?null:before.site)
         !==_auCanon(after.site===undefined?null:after.site))
        issues.push(_auIssue('CONSTRAINT_VIOLATION','site',
          'must_not_change SITE was violated'));
    } else if(subject==='BUILDING_TRANSFORM'){
      if(_auCanon(before.placement===undefined?null:before.placement)
         !==_auCanon(after.placement===undefined?null:after.placement))
        issues.push(_auIssue('CONSTRAINT_VIOLATION','placement',
          'must_not_change BUILDING_TRANSFORM was violated'));
    } else if(subject==='DOOR_COUNT'||subject==='WINDOW_COUNT'||subject==='OBJECT_COUNT'){
      const key={DOOR_COUNT:'doors',WINDOW_COUNT:'windows',OBJECT_COUNT:'objects'}[subject];
      const cnt=m=>_auAllRooms(m).reduce((s,p)=>s+((p[1][key]||[]).length),0);
      const cb=cnt(before), ca=cnt(after);
      if(cb!==ca) issues.push(_auIssue('CONSTRAINT_VIOLATION',key,
        'must_not_change '+subject+' was violated ('+cb+' -> '+ca+')'));
    } else if(subject==='LEVEL_COUNT'){
      if((before.levels||[]).length!==(after.levels||[]).length)
        issues.push(_auIssue('CONSTRAINT_VIOLATION','levels',
          'must_not_change LEVEL_COUNT was violated'));
    } else if(subject==='SPACE_COUNT'){
      if(Object.keys(sb).length!==Object.keys(sa).length)
        issues.push(_auIssue('CONSTRAINT_VIOLATION','spaces',
          'must_not_change SPACE_COUNT was violated')); } });
  (cons.must_preserve||[]).forEach(subject=>{
    if(subject==='HOSTED_OPENINGS'){
      Object.keys(sb).sort(_scmp).forEach(k=>{ ['doors','windows'].forEach(key=>{
        if((sb[k][key]||[]).length!==(((sa[k]||{})[key])||[]).length)
          issues.push(_auIssue('CONSTRAINT_VIOLATION',k,
            'must_preserve HOSTED_OPENINGS was violated')); }); });
    } else if(subject==='SPACE_IDS'){
      if(JSON.stringify(Object.keys(sb).sort(_scmp))
         !==JSON.stringify(Object.keys(sa).sort(_scmp)))
        issues.push(_auIssue('CONSTRAINT_VIOLATION','space_ids',
          'must_preserve SPACE_IDS was violated'));
    } else if(subject==='STAIR_COUNT'){
      const st=m=>_auAllRooms(m).reduce((s,p)=>s+(p[1].objects||[]).filter(o=>{
        const k=String(o.kind||'').toLowerCase(); return k==='stairs'||k==='stair'; }).length,0);
      if(st(before)!==st(after)) issues.push(_auIssue('CONSTRAINT_VIOLATION','stairs',
        'must_preserve STAIR_COUNT was violated'));
    } else if(subject==='OBJECT_IDS'){
      const ob=m=>{ const o=[]; _auAllRooms(m).forEach(p=>{
        (p[1].objects||[]).forEach((x,i)=>o.push(p[0]+'.'+p[1].id+'.obj_'+i)); });
        return o.sort(_scmp); };
      if(JSON.stringify(ob(before))!==JSON.stringify(ob(after)))
        issues.push(_auIssue('CONSTRAINT_VIOLATION','objects',
          'must_preserve OBJECT_IDS was violated'));
    } else if(subject==='SPACE_ADJACENCY'){
      const ad=m=>{ const o=[]; _auAllRooms(m).forEach(p=>{
        o.push(p[0]+'.'+p[1].id+':'+JSON.stringify((p[1].rect||[0,0,0,0]).map(_auNum))); });
        return o.sort(_scmp); };
      if(JSON.stringify(ad(before))!==JSON.stringify(ad(after)))
        issues.push(_auIssue('CONSTRAINT_VIOLATION','adjacency',
          'must_preserve SPACE_ADJACENCY was violated')); } });
  if(cons.max_delta_m!==undefined&&cons.max_delta_m!==null){
    let worst=0;
    keys.forEach(k=>{
      const rb=(sb[k]||{}).rect||[0,0,0,0], ra=(sa[k]||{}).rect||[0,0,0,0];
      for(let i=0;i<4;i++) worst=Math.max(worst,
        Math.abs((_auNum(ra[i])||0)-(_auNum(rb[i])||0))); });
    if(worst>cons.max_delta_m+1e-9)
      issues.push(_auIssue('CONSTRAINT_VIOLATION','max_delta_m',
        'the edit moved geometry by '+worst.toFixed(3)+
        ' m, beyond the stated maximum of '+Number(cons.max_delta_m).toFixed(3)+' m')); }
  if(cons.allowed_scope&&cons.allowed_scope.length
     &&cons.allowed_scope.indexOf(cmd.discipline)<0)
    issues.push(_auIssue('AUTHORING_SCOPE_VIOLATION',cmd.discipline,
      'the command discipline is outside the allowed scope'));
  return issues; }

/* --------------------------------------------------- تماسك النموذج ----- */
function auValidateModelIntegrity(model,buildingId){
  const issues=[];
  if(!model||typeof model!=='object'||Array.isArray(model))
    return _auResult([_auIssue('MODEL_INTEGRITY_FAILURE','model','model must be an object')],{});
  issues.push(...auOpeningIdentityIssues(model,buildingId));
  let levels=model.levels;
  if(!Array.isArray(levels)||!levels.length){
    issues.push(_auIssue('MODEL_INTEGRITY_FAILURE','levels',
      'a model must carry at least one level'));
    levels=[]; }
  const seen={};
  levels.forEach(lv=>{
    if(!lv||typeof lv!=='object'||Array.isArray(lv)){
      issues.push(_auIssue('MODEL_INTEGRITY_FAILURE','levels','a level must be an object'));
      return; }
    const i=String(lv.index);
    if(Object.prototype.hasOwnProperty.call(seen,i))
      issues.push(_auIssue('ID_COLLISION',i,'duplicate level index'));
    seen[i]=true;
    if(!Object.prototype.hasOwnProperty.call(_auTemplates(model),String(lv.template)))
      issues.push(_auIssue('MODEL_INTEGRITY_FAILURE',String(lv.template),
        'a level references a floor template that does not exist')); });
  const per={};
  _auAllRooms(model).forEach(p=>{
    const t=p[0], r=p[1], rid=String(r.id||'');
    if(!rid){ issues.push(_auIssue('MODEL_INTEGRITY_FAILURE',t,'a space carries no id')); return; }
    const key=t+'.'+rid;
    if(Object.prototype.hasOwnProperty.call(per,key))
      issues.push(_auIssue('ID_COLLISION',key,'duplicate space id on one template'));
    const rect=r.rect;
    if(!Array.isArray(rect)||rect.length!==4){
      issues.push(_auIssue('MODEL_INTEGRITY_FAILURE',key,'a space carries no valid rectangle'));
      per[key]=null; return; }
    const vals=rect.map(_auNum);
    if(vals.some(v=>v===null)){
      issues.push(_auIssue('MODEL_INTEGRITY_FAILURE',key,
        'a space rectangle carries a non-finite value'));
      per[key]=null; return; }
    if(vals[2]<=0||vals[3]<=0)
      issues.push(_auIssue('MODEL_INTEGRITY_FAILURE',key,'a space side is zero or negative'));
    if(vals.some(v=>Math.abs(v)>AU_MAX_COORD))
      issues.push(_auIssue('COORDINATE_OUT_OF_BOUNDS',key,
        'a space rectangle is outside the declared safe bound'));
    per[key]=[t,vals];
    ['doors','windows'].forEach(k=>{ (r[k]||[]).forEach((op,i)=>{
      if(!op||typeof op!=='object'||Array.isArray(op)){
        issues.push(_auIssue('MODEL_INTEGRITY_FAILURE',key,
          'an opening record is not an object')); return; }
      const edge=String(op.edge||'N').toUpperCase().slice(0,1);
      if(['N','S','E','W'].indexOf(edge)<0){
        issues.push(_auIssue('HOST_INVALID',(op.id||key+'.'+k.slice(0,-1)+'_'+i),
          'the opening names no valid host edge')); return; }
      const span=(edge==='N'||edge==='S')?vals[2]:vals[3];
      const off=_auNum(op.offset), wid=_auNum(op.width)||0;
      if(off===null){ issues.push(_auIssue('HOST_INVALID',(op.id||key+'.'+k.slice(0,-1)+'_'+i),
        'the opening carries no finite offset')); return; }
      if(off-wid/2<-1e-9||off+wid/2>span+1e-9)
        issues.push(_auIssue('OPENING_OUT_OF_RANGE',(op.id||key+'.'+k.slice(0,-1)+'_'+i),
          'the opening does not fit its host edge')); }); });
    (r.objects||[]).forEach((o,i)=>{
      if(!o||typeof o!=='object'||Array.isArray(o)||!o.kind)
        issues.push(_auIssue('MODEL_INTEGRITY_FAILURE',key+'.obj_'+i,
          'a semantic object carries no kind')); }); });
  const byT={};
  Object.keys(per).forEach(k=>{ const v=per[k]; if(!v) return;
    if(!byT[v[0]]) byT[v[0]]=[]; byT[v[0]].push([k,v[1]]); });
  Object.keys(byT).sort(_scmp).forEach(t=>{
    const items=byT[t].slice().sort((a,b)=>_scmp(a[0],b[0]));
    for(let a=0;a<items.length;a++) for(let b=a+1;b<items.length;b++){
      const ra=items[a][1], rb=items[b][1];
      if(ra[0]<rb[0]+rb[2]-1e-9&&rb[0]<ra[0]+ra[2]-1e-9
         &&ra[1]<rb[1]+rb[3]-1e-9&&rb[1]<ra[1]+ra[3]-1e-9)
        issues.push(_auIssue('SPACE_OVERLAP',items[a][0]+' | '+items[b][0],
          'two spaces on the same template overlap')); } });
  const site=model.site;
  if(site!==undefined&&site!==null) ['w','d'].forEach(k=>{
    const v=_auNum((site||{})[k]);
    if(v===null||v<=0) issues.push(_auIssue('MODEL_INTEGRITY_FAILURE','site.'+k,
      'the site dimension is missing or not positive')); });
  return _auResult(issues,{checked:'structural coherence only; this is not a code, safety, '+
    'structural, MEP or fire compliance statement',compliance:'NOT_EVALUATED'}); }

/* -------------------------------------------------------- الاعتماديات -- */
function auDependencyImpact(command,model,buildingId){
  const bid=buildingId||'bld_0';
  const n=auNormaliseCommand(command,null,null,null);
  if(!n.valid||!n.command) return _auResult(n.issues,{impact:null});
  const cmd=n.command;
  const arts=AU_DEPENDENCY_GRAPH[cmd.type]||[];
  const a=_auApply(model,cmd,bid);
  const affected=(a.dependencies||[]).slice();
  const detail=[];
  const res=cmd.target_id?auResolveTarget(model,cmd.target_id,bid):{kind:null};
  if(res.kind==='SPACE'){
    const room=_auFindRoom(model,res.template,res.room_id)||{};
    ['doors','windows'].forEach(key=>{ (room[key]||[]).forEach((op,i)=>{
      detail.push(_auOpeningReference(model,res.template,res.room_id,key,i)); }); });
    (room.objects||[]).forEach((o,i)=>{
      detail.push(res.template+'.'+res.room_id+'.obj_'+i); }); }
  const ids=Array.from(new Set(affected.concat(detail))).sort(_scmp);
  return _auResult([],{impact:{command_type:cmd.type,discipline:cmd.discipline,
    invalidates:arts.slice(),
    not_invalidated:AU_DEPENDENCY_ARTIFACTS.filter(x=>arts.indexOf(x)<0),
    affected_element_ids:ids,affected_count:ids.length,
    structure_mutated:false,mep_mutated:false,fls_mutated:false,
    note:'a factual dependency report. Nothing here is an engineering recommendation, and '+
         'no structural, MEP or fire/life-safety element is moved, rerouted or redesigned '+
         'by an architectural edit.'}}); }

/* ------------------------------------------------------------ المعاينة - */
function auPreviewCommand(model,command,baseRevision,buildingId,snap,gridM){
  const bid=buildingId||'bld_0';
  const beforeHash=auModelHash(model,'building',bid);
  const n=auNormaliseCommand(command,baseRevision,snap,gridM);
  if(!n.valid||!n.command)
    return _auResult(n.issues,{preview:null,candidate:null,
      base_model_hash:beforeHash,state:'INVALID_COMMAND'});
  const cmd=n.command;
  if(cmd.base_revision!==null&&baseRevision!==undefined&&baseRevision!==null
     &&cmd.base_revision!==baseRevision)
    return _auResult([_auIssue('STALE_BASE_REVISION',cmd.base_revision,
      'the command was authored against a different revision')],
      {preview:null,candidate:null,base_model_hash:beforeHash,
       state:'STALE_BASE_REVISION'});
  const a=_auApply(model,cmd,bid);
  const issues=n.issues.concat(a.issues);
  if(!a.candidate)
    return _auResult(issues,{preview:null,candidate:null,base_model_hash:beforeHash,
      dependencies:a.dependencies||[],state:'REJECTED'});
  const candidate=a.candidate;
  issues.push.apply(issues,_auEnforceConstraints(cmd,model,candidate,bid));
  const integ=auValidateModelIntegrity(candidate,bid);
  issues.push.apply(issues,integ.issues);
  const afterHash=auModelHash(candidate,'building',bid);
  const preview={command_id:cmd.command_id,command_hash:cmd.command_hash,
    base_model_hash:beforeHash,candidate_model_hash:afterHash,
    changed_paths:a.changed_paths||[],dependencies:a.dependencies||[],
    dependency_breaking:a.dependency_breaking||[],
    requires_confirmation:(a.dependency_breaking||[]).length>0
      ||AU_DESTRUCTIVE.indexOf(cmd.type)>=0,
    model_changed:afterHash!==beforeHash,preview:true,committed:false,
    compliance:'NOT_EVALUATED',
    note:'a candidate model built from a copy. The canonical engineering model is unchanged '+
         'and stays unchanged unless a commit is performed explicitly.'};
  const state=_auHasError(issues)?'REJECTED':'PREVIEWED';
  return _auResult(issues,{preview:preview,candidate:candidate,
    base_model_hash:beforeHash,candidate_model_hash:afterHash,state:state}); }

function auCancelPreview(project){
  project.authoring.pending_commands=[];
  project.authoring.preview=null;
  project.authoring.validation=[];
  project.authoring.transaction_status='IDLE';
  return _auResult([],{state:'IDLE',model_hash:project.model_hash,
    note:'preview cancelled; zero engineering change'}); }

/* ---------------------------------------------------------- المشروع ---- */
function auCreateProject(model,buildingId,source,actorId){
  const bid=buildingId||'bld_0';
  const m=_auCopy(model);
  const h=auModelHash(m,'building',bid);
  const rev='rev:'+_auSha16({parent:null,model_hash:h,command:null});
  const src=_auEnum(source);
  const record={revision_id:rev,parent_revision_id:null,model_hash:h,
    command_id:null,command_hash:null,
    authoring_source:(AU_SOURCES.indexOf(src)>=0)?src:'IMPORT',
    actor_id:(typeof actorId==='string')?actorId:null,
    created_at:null,summary:'initial revision',changed_paths:[],
    reverts_revision_id:null};
  const snaps={}; snaps[rev]=_auCopy(m);
  return {schema:AU_SCHEMA,version:AU_VERSION,engine_version:AU_ENGINE_VERSION,
    building_id:bid,model:m,model_hash:h,current_revision:rev,
    history:[record],audit_log:[],revision_models:snaps,
    authoring:{base_revision:rev,working_revision:null,pending_commands:[],
      preview:null,validation:[],transaction_status:'IDLE',history:[]},
    note:'the canonical engineering model and its revision pointer. Transient authoring '+
         'state lives beside the model, never inside it.'}; }

function auBeginEdit(project){
  const a=project.authoring;
  a.transaction_status='DRAFT';
  a.base_revision=project.current_revision;
  a.pending_commands=[]; a.preview=null; a.validation=[];
  return _auResult([],{state:'DRAFT',base_revision:a.base_revision}); }

function auAuthoringState(project){
  const a=project.authoring;
  return {base_revision:a.base_revision,working_revision:a.working_revision,
    pending_commands:_auCopy(a.pending_commands),preview:_auCopy(a.preview),
    validation:_auCopy(a.validation),transaction_status:a.transaction_status,
    history:_auCopy(a.history),current_revision:project.current_revision,
    model_hash:project.model_hash,runtime_state_present:false,
    note:'transient authoring state; it is never serialised into the canonical model'}; }

/* ------------------------------------------------------------ المعاملة - */
function _auConfirmationDigest(commands,baseRevision){
  return _auSha16({commands:commands.map(c=>c.command_hash),base_revision:baseRevision}); }

function auValidateTransaction(project,commands,buildingId){
  const bid=buildingId||project.building_id||'bld_0';
  const issues=[];
  if(!Array.isArray(commands))
    return _auResult([_auIssue('INVALID_COMMAND','commands','a list of commands is required')],
      {transaction:null,state:'INVALID_COMMAND'});
  if(!commands.length)
    return _auResult([_auIssue('INVALID_COMMAND','commands','a transaction needs a command')],
      {transaction:null,state:'INVALID_COMMAND'});
  if(commands.length>Number(AU_LIMITS.max_commands_per_transaction))
    return _auResult([_auIssue('BATCH_TOO_LARGE',String(commands.length),
      'the transaction exceeds the declared command cap of '+
      Number(AU_LIMITS.max_commands_per_transaction))],
      {transaction:null,state:'REJECTED'});
  const base=project.current_revision;
  let working=_auCopy(project.model);
  const baseHash=project.model_hash;
  const norm=[], results=[]; let changed=[], deps=[], breaks=[];
  commands.forEach((raw,i)=>{
    const br=(raw&&typeof raw==='object'&&!Array.isArray(raw)
      &&raw.base_revision!==undefined)?raw.base_revision:null;
    const n=auNormaliseCommand(raw,br,null,null);
    if(!n.valid||!n.command){
      results.push({index:i,command_id:null,accepted:false,issues:n.issues});
      issues.push.apply(issues,n.issues); return; }
    const cmd=n.command;
    if(cmd.base_revision!==null&&cmd.base_revision!==base){
      const iss=[_auIssue('STALE_BASE_REVISION',cmd.base_revision,
        'the command was authored against revision '+cmd.base_revision+
        ' but the current revision is '+base)];
      results.push({index:i,command_id:cmd.command_id,accepted:false,issues:iss});
      issues.push.apply(issues,iss); return; }
    const a=_auApply(working,cmd,bid);
    if(!a.candidate){
      results.push({index:i,command_id:cmd.command_id,accepted:false,issues:a.issues});
      issues.push.apply(issues,a.issues); return; }
    const cons=_auEnforceConstraints(cmd,working,a.candidate,bid);
    if(cons.length){
      results.push({index:i,command_id:cmd.command_id,accepted:false,
        issues:_auSortIssues(cons)});
      issues.push.apply(issues,cons); return; }
    working=a.candidate;
    norm.push(cmd);
    changed=changed.concat(a.changed_paths||[]);
    deps=deps.concat(a.dependencies||[]);
    breaks=breaks.concat(a.dependency_breaking||[]);
    results.push({index:i,command_id:cmd.command_id,accepted:true,issues:a.issues,
      changed_paths:a.changed_paths||[]});
    issues.push.apply(issues,a.issues); });

  if(norm.length){
    const integ=auValidateModelIntegrity(working,bid);
    issues.push.apply(issues,integ.issues); }
  const candHash=norm.length?auModelHash(working,'building',bid):baseHash;
  const needsConfirm=norm.some(c=>AU_DESTRUCTIVE.indexOf(c.type)>=0)||breaks.length>0;
  const ai=norm.filter(c=>c.source==='AI_PROPOSAL');
  const txn={transaction_id:'txn:'+_auSha16({commands:norm.map(c=>c.command_hash),base:base}),
    base_revision:base,base_model_hash:baseHash,candidate_model_hash:candHash,
    commands:norm,command_results:results,
    changed_paths:Array.from(new Set(changed)).sort(_scmp),
    dependencies:Array.from(new Set(deps)).sort(_scmp),
    dependency_breaking:Array.from(new Set(breaks)).sort(_scmp),
    requires_confirmation:needsConfirm,
    confirmation_digest:norm.length?_auConfirmationDigest(norm,base):null,
    contains_ai_proposal:ai.length>0,atomic:true,compliance:'NOT_EVALUATED',
    note:'commit is all-or-nothing. A single failing command leaves the canonical model '+
         'byte-identical.'};
  let state=(!_auHasError(issues)&&norm.length)?'VALIDATED':'REJECTED';
  if(issues.some(i=>i.code==='STALE_BASE_REVISION')) state='STALE_BASE_REVISION';
  if(issues.some(i=>i.code==='DEPENDENCY_CONFLICT')) state='CONFLICT';
  if(issues.some(i=>i.code==='INVALID_COMMAND'||i.code==='COMMAND_NOT_ALLOWED'
     ||i.code==='COMMAND_NOT_IMPLEMENTED')) state='INVALID_COMMAND';
  return _auResult(issues,{transaction:txn,candidate:norm.length?working:null,state:state}); }

function auCommitTransaction(project,commands,opts){
  opts=opts||{};
  const bid=opts.building_id||project.building_id||'bld_0';
  const confirm=opts.confirm, ack=!!opts.acknowledge_warnings;
  const beforeHash=project.model_hash, beforeModel=_auCanon(project.model);
  const v=auValidateTransaction(project,commands,bid);
  const issues=v.issues.slice();
  const txn=v.transaction;
  if(!v.valid||!txn||!v.candidate)
    return _auResult(issues,{committed:false,state:v.state||'REJECTED',
      revision:project.current_revision,model_hash:beforeHash,transaction:txn,
      note:'rejected; the canonical model is byte-identical'});
  if(txn.contains_ai_proposal&&!(typeof confirm==='string'&&confirm))
    issues.push(_auIssue('AI_COMMIT_NOT_PERMITTED','AI_PROPOSAL',
      'an AI-proposed command may never commit automatically; an explicit confirmation '+
      'token is required'));
  if(txn.requires_confirmation){
    if(!(typeof confirm==='string'&&confirm))
      issues.push(_auIssue('CONFIRMATION_REQUIRED',txn.transaction_id,
        'this transaction is destructive or dependency-breaking and needs an explicit '+
        'confirmation token'));
    else if(confirm!==txn.confirmation_digest)
      issues.push(_auIssue('CONFIRMATION_REQUIRED',txn.transaction_id,
        'the confirmation token does not match this transaction')); }
  const warnings=issues.filter(i=>i.severity==='WARNING');
  const policy=AU_COMMIT_POLICY.warning_policy;
  if(warnings.length&&policy==='ALLOW_WITH_EXPLICIT_ACKNOWLEDGEMENT'&&!ack)
    issues.push(_auIssue('CONFIRMATION_REQUIRED','warnings',
      'the declared policy requires warnings to be acknowledged explicitly before commit'));
  else if(warnings.length&&policy==='BLOCK')
    issues.push(_auIssue('MODEL_INTEGRITY_FAILURE','warnings',
      'the declared policy blocks a commit carrying warnings'));
  if(_auHasError(issues)){
    if(_auCanon(project.model)!==beforeModel)
      throw new Error('authoring mutated the canonical model on a rejected commit');
    return _auResult(issues,{committed:false,state:'REJECTED',
      revision:project.current_revision,model_hash:beforeHash,transaction:txn,
      note:'rejected; the canonical model is byte-identical'}); }

  const candidate=v.candidate;
  const newHash=auModelHash(candidate,'building',bid);
  const parent=project.current_revision;
  const rev='rev:'+_auSha16({parent:parent,model_hash:newHash,
    commands:txn.commands.map(c=>c.command_hash)});
  if(project.history.some(r=>r.revision_id===rev))
    return _auResult([_auIssue('ID_COLLISION',rev,
      'a revision with this deterministic id already exists')],
      {committed:false,state:'REJECTED',revision:parent,model_hash:beforeHash,
       transaction:txn});
  const src=_auEnum(opts.source);
  const record={revision_id:rev,parent_revision_id:parent,model_hash:newHash,
    command_id:txn.commands.length?txn.commands[0].command_id:null,
    command_hash:txn.commands.length?txn.commands[0].command_hash:null,
    command_ids:txn.commands.map(c=>c.command_id),
    authoring_source:(AU_SOURCES.indexOf(src)>=0)?src
      :(txn.commands.length?txn.commands[0].source:'USER'),
    actor_id:(typeof opts.actor_id==='string')?opts.actor_id:null,
    created_at:(typeof opts.created_at==='string')?opts.created_at:null,
    summary:txn.commands.map(c=>c.type).join(', '),
    changed_paths:txn.changed_paths,reverts_revision_id:null};
  const np={};
  Object.keys(project).forEach(k=>{np[k]=project[k];});
  np.model=candidate; np.model_hash=newHash; np.current_revision=rev;
  np.history=project.history.concat([record]);
  const audit={transaction_id:txn.transaction_id,
    command_ids:txn.commands.map(c=>c.command_id),
    command_hashes:txn.commands.map(c=>c.command_hash),
    source:record.authoring_source,actor_id:record.actor_id,
    base_revision:parent,new_revision:rev,
    model_hash_before:beforeHash,model_hash_after:newHash,
    changed_paths:txn.changed_paths,
    validation_summary:{errors:0,warnings:warnings.length,
      infos:issues.filter(i=>i.severity==='INFO').length},
    created_at:record.created_at,confirmation_provided:!!confirm,
    warning_acknowledged:!!ack,
    note:'no secret, token or AI reasoning trace is recorded here'};
  np.audit_log=project.audit_log.concat([audit]);
  const snaps=Object.assign({},project.revision_models||{});
  snaps[rev]=_auCopy(candidate);
  np.revision_models=snaps;
  let stale=[];
  txn.commands.forEach(c=>{ stale=stale.concat(AU_DEPENDENCY_GRAPH[c.type]||[]); });
  np.authoring={base_revision:rev,working_revision:null,pending_commands:[],
    preview:null,validation:[],transaction_status:'IDLE',
    history:project.authoring.history.concat([txn.transaction_id])};
  if(_auCanon(project.model)!==beforeModel)
    throw new Error('authoring mutated the canonical model during a commit');
  return _auResult(issues,{committed:true,state:'COMMITTED',project:np,revision:rev,
    parent_revision:parent,model_hash:newHash,previous_model_hash:beforeHash,
    transaction:txn,stale_artifacts:Array.from(new Set(stale)).sort(_scmp),audit:audit,
    note:'a new revision. The previous model object was not mutated and stays addressable '+
         'through its own hash.'}); }

/* --------------------------------------------------- التراجع والإعادة -- */
function _auRevisionModel(project,revisionId){
  const snaps=project.revision_models||{};
  return Object.prototype.hasOwnProperty.call(snaps,revisionId)
    ?_auCopy(snaps[revisionId]):null; }

function auUndo(project,revisionId,createdAt,buildingId){
  const bid=buildingId||project.building_id||'bld_0';
  const hist=project.history;
  const target=revisionId||project.current_revision;
  let idx=-1;
  hist.forEach((r,i)=>{ if(r.revision_id===target&&idx<0) idx=i; });
  if(idx<0||idx===0)
    return _auResult([_auIssue('UNDO_TARGET_INVALID',target,
      'no such revision, or it is the initial revision')],
      {project:null,state:'REJECTED',model_hash:project.model_hash});
  const parentId=hist[idx-1].revision_id;
  const restored=_auRevisionModel(project,parentId);
  if(restored===null)
    return _auResult([_auIssue('UNDO_TARGET_INVALID',parentId,
      'the parent revision model could not be reconstructed')],
      {project:null,state:'REJECTED',model_hash:project.model_hash});
  const newHash=auModelHash(restored,'building',bid);
  const parent=project.current_revision;
  const rev='rev:'+_auSha16({parent:parent,model_hash:newHash,reverts:target});
  const record={revision_id:rev,parent_revision_id:parent,model_hash:newHash,
    command_id:null,command_hash:null,command_ids:[],authoring_source:'SYSTEM_TOOL',
    actor_id:null,created_at:(typeof createdAt==='string')?createdAt:null,
    summary:'undo of '+target,
    changed_paths:(hist[idx].changed_paths||[]).slice(),reverts_revision_id:target};
  const np={}; Object.keys(project).forEach(k=>{np[k]=project[k];});
  np.model=restored; np.model_hash=newHash; np.current_revision=rev;
  np.history=hist.concat([record]);
  const snaps=Object.assign({},project.revision_models||{});
  snaps[rev]=_auCopy(restored); np.revision_models=snaps;
  np.audit_log=project.audit_log.concat([{
    transaction_id:'txn:undo:'+_auSha16({reverts:target,parent:parent}),
    command_ids:[],command_hashes:[],source:'SYSTEM_TOOL',actor_id:null,
    base_revision:parent,new_revision:rev,model_hash_before:project.model_hash,
    model_hash_after:newHash,changed_paths:record.changed_paths,
    validation_summary:{errors:0,warnings:0,infos:0},created_at:record.created_at,
    confirmation_provided:true,warning_acknowledged:true,
    note:'undo is a new forward revision; no history entry was removed'}]);
  np.authoring=Object.assign({},project.authoring); np.authoring.base_revision=rev;
  return _auResult([],{project:np,state:'COMMITTED',revision:rev,reverts:target,
    model_hash:newHash,history_length:np.history.length,
    note:'undo appended a new revision; nothing was deleted from history'}); }

function auRedo(project,revisionId,createdAt,buildingId){
  const bid=buildingId||project.building_id||'bld_0';
  const hist=project.history;
  let cur=null;
  hist.forEach(r=>{ if(r.revision_id===project.current_revision) cur=r; });
  let target=revisionId;
  if(target===undefined||target===null){
    if(!cur||!cur.reverts_revision_id)
      return _auResult([_auIssue('UNDO_TARGET_INVALID',project.current_revision,
        'there is nothing to redo: the current revision is not an undo')],
        {project:null,state:'REJECTED',model_hash:project.model_hash});
    target=cur.reverts_revision_id; }
  const restored=_auRevisionModel(project,target);
  if(restored===null)
    return _auResult([_auIssue('UNDO_TARGET_INVALID',target,
      'the revision model could not be reconstructed')],
      {project:null,state:'REJECTED',model_hash:project.model_hash});
  const newHash=auModelHash(restored,'building',bid);
  const parent=project.current_revision;
  const rev='rev:'+_auSha16({parent:parent,model_hash:newHash,redoes:target});
  const record={revision_id:rev,parent_revision_id:parent,model_hash:newHash,
    command_id:null,command_hash:null,command_ids:[],authoring_source:'SYSTEM_TOOL',
    actor_id:null,created_at:(typeof createdAt==='string')?createdAt:null,
    summary:'redo of '+target,changed_paths:[],reverts_revision_id:null,
    redoes_revision_id:target};
  const np={}; Object.keys(project).forEach(k=>{np[k]=project[k];});
  np.model=restored; np.model_hash=newHash; np.current_revision=rev;
  np.history=hist.concat([record]);
  const snaps=Object.assign({},project.revision_models||{});
  snaps[rev]=_auCopy(restored); np.revision_models=snaps;
  np.audit_log=project.audit_log.slice();
  np.authoring=Object.assign({},project.authoring); np.authoring.base_revision=rev;
  return _auResult([],{project:np,state:'COMMITTED',revision:rev,redoes:target,
    model_hash:newHash,history_length:np.history.length,
    note:'redo appended a new revision; the mutable pointer never moved back'}); }

/* ------------------------------------------------------------ الفروق --- */
function _auFlatten(model,prefix){
  const out={};
  const walk=(v,p)=>{
    if(v&&typeof v==='object'&&!Array.isArray(v)){
      Object.keys(v).sort(_scmp).forEach(k=>walk(v[k],p?(p+'.'+k):String(k)));
    } else if(Array.isArray(v)){
      v.forEach((x,i)=>walk(x,p+'['+i+']'));
    } else { out[p]=v; } };
  walk(model,prefix||'');
  return out; }

function auRevisionDiff(beforeModel,afterModel){
  const a=_auFlatten(beforeModel,''), b=_auFlatten(afterModel,'');
  const added=Object.keys(b).filter(k=>!(k in a)).sort(_scmp);
  const removed=Object.keys(a).filter(k=>!(k in b)).sort(_scmp);
  const changed=Object.keys(a).filter(k=>(k in b)
    &&JSON.stringify(a[k])!==JSON.stringify(b[k])).sort(_scmp);
  const els=m=>{ const o={};
    _auAllRooms(m).forEach(p=>{o[p[0]+'.'+p[1].id]=p[1];}); return o; };
  const ea=els(beforeModel), eb=els(afterModel);
  return {added_paths:added,removed_paths:removed,changed_paths:changed,
    added_elements:Object.keys(eb).filter(k=>!(k in ea)).sort(_scmp),
    removed_elements:Object.keys(ea).filter(k=>!(k in eb)).sort(_scmp),
    changed_elements:Object.keys(ea).filter(k=>(k in eb)
      &&_auCanon(ea[k])!==_auCanon(eb[k])).sort(_scmp),
    property_changes:changed.map(k=>({path:k,before:a[k],after:b[k]})),
    counts:{added:added.length,removed:removed.length,changed:changed.length}}; }

/* --------------------------------------------- الخواصّ القابلة للتحرير - */
function _auFieldConstraints(name){
  if(name==='space.rect') return {min_side_m:AU_MIN_DIM,max_side_m:AU_MAX_DIM,
    max_abs_coordinate_m:AU_MAX_COORD};
  if(name==='opening.width_m'||name==='opening.height_m'||name==='opening.sill_m')
    return {min_m:AU_MIN_DIM,max_m:AU_MAX_DIM};
  if(name==='object.x'||name==='object.z'||name==='building.position')
    return {max_abs_coordinate_m:AU_MAX_COORD};
  if(name==='site.w'||name==='site.d') return {min_m:AU_MIN_DIM,max_m:AU_MAX_DIM};
  if(name==='building.rotation_deg') return {min_deg:0.0,max_deg:360.0};
  return {}; }

function auEditableProperties(model,targetId,buildingId){
  const bid=buildingId||'bld_0';
  const res=auResolveTarget(model,targetId,bid);
  if(res.kind===null||res.kind===undefined)
    return _auResult(res.issues,{properties:null});
  const kind=res.kind, fields=[];
  const add=(name,value,cls,source)=>{ fields.push({field:name,
    value:(value===null||value===undefined)?AU_NOT_SPECIFIED:value,
    editability:cls,source:source||'model',constraints:_auFieldConstraints(name)}); };
  if(kind==='SPACE'){
    const room=_auFindRoom(model,res.template,res.room_id);
    const rect=room.rect||[];
    add('space.id',room.id,AU_EDITABILITY['space.id'],'model');
    add('space.name',room.name,AU_EDITABILITY['space.name'],'model');
    add('space.rect',rect,AU_EDITABILITY['space.rect'],'model');
    let area=null;
    if(rect.length===4&&_auNum(rect[2])!==null&&_auNum(rect[3])!==null)
      area=_auQ(_auNum(rect[2])*_auNum(rect[3]));
    add('space.area_m2',area,AU_EDITABILITY['space.area_m2'],'derived');
    add('space.boundary_basis','rectangle_edges',
      AU_EDITABILITY['space.boundary_basis'],'derived');
    add('space.wall_height_m',room.height,AU_EDITABILITY['space.wall_height_m'],'model');
  } else if(kind==='DOOR'||kind==='WINDOW'){
    const room=_auFindRoom(model,res.template,res.room_id);
    const op=room[res.opening_key][res.opening_index];
    add('opening.id',op.id||targetId,op.id?'READ_ONLY':AU_EDITABILITY['opening.id'],op.id?'model':'derived');
    add('opening.edge',op.edge,AU_EDITABILITY['opening.edge'],'model');
    add('opening.offset',op.offset,AU_EDITABILITY['opening.offset'],'model');
    add('opening.width_m',op.width,AU_EDITABILITY['opening.width_m'],'model');
    add('opening.height_m',op.height,AU_EDITABILITY['opening.height_m'],'model');
    if(kind==='WINDOW') add('opening.sill_m',op.sill,AU_EDITABILITY['opening.sill_m'],'model');
    add('opening.host_wall_id',null,AU_EDITABILITY['opening.host_wall_id'],'derived');
    add('opening.clear_width_m',null,AU_EDITABILITY['opening.clear_width_m'],'unknown');
    add('opening.swing_direction',null,AU_EDITABILITY['opening.swing_direction'],'unknown');
  } else if(kind==='OBJECT'){
    const room=_auFindRoom(model,res.template,res.room_id);
    const o=room.objects[res.object_index];
    add('object.kind',o.kind,AU_EDITABILITY['object.kind'],'model');
    add('object.x',o.x,AU_EDITABILITY['object.x'],'model');
    add('object.z',o.z,AU_EDITABILITY['object.z'],'model');
    add('object.count',o.count,AU_EDITABILITY['object.count'],'model');
  } else if(kind==='LEVEL'){
    let lv=null; (model.levels||[]).forEach(l=>{ if(l.index===res.level_index) lv=l; });
    add('level.index',lv?lv.index:null,AU_EDITABILITY['level.index'],'model');
    add('level.template',lv?lv.template:null,AU_EDITABILITY['level.template'],'model');
    add('level.name',lv?lv.name:null,AU_EDITABILITY['level.name'],'model');
    add('level.elevation_m',null,AU_EDITABILITY['level.elevation_m'],'derived');
  } else if(kind==='SITE'){
    const site=model.site||{};
    add('site.w',site.w,AU_EDITABILITY['site.w'],'model');
    add('site.d',site.d,AU_EDITABILITY['site.d'],'model');
  } else if(kind==='BUILDING'){
    const pl=model.placement||{};
    add('building.position',pl.position,AU_EDITABILITY['building.position'],'model');
    add('building.rotation_deg',pl.rotation_deg,
      AU_EDITABILITY['building.rotation_deg'],'model');
  } else if(kind==='WALL'){
    add('wall.id',targetId,AU_EDITABILITY['wall.id'],'derived');
    add('wall.start',null,AU_EDITABILITY['wall.start'],'derived');
    add('wall.end',null,AU_EDITABILITY['wall.end'],'derived');
    add('wall.length_m',null,AU_EDITABILITY['wall.length_m'],'derived');
    add('wall.axis',null,AU_EDITABILITY['wall.axis'],'derived');
    add('wall.thickness_m',null,AU_EDITABILITY['wall.thickness_m'],'unknown');
    add('wall.exposure',null,AU_EDITABILITY['wall.exposure'],'derived'); }
  add('model_hash',_auShort(auModelHash(model,'building',bid)),
    AU_EDITABILITY['model_hash'],'derived');
  add('visual.material',null,AU_EDITABILITY['visual.material'],'presentation');
  const locks=model._authoring_locks||{};
  const isLocked=Object.prototype.hasOwnProperty.call(locks,targetId);
  return _auResult([],{properties:{target_id:targetId,kind:kind,locked:isLocked,
    lock_reason:isLocked?locks[targetId].reason:null,fields:fields,
    editable_count:fields.filter(f=>f.editability==='EDITABLE').length,
    note:'a DERIVED value changes only by editing its source; a DISPLAY_ONLY value is '+
         'presentation and never engineering data; an UNKNOWN value is not stated by the '+
         'source and is not invented'}}); }

/* ------------------------------------------------------ اقتراح الذكاء -- */
function auProposeCommand(command,rationale,baseRevision){
  const n=auNormaliseCommand(command,baseRevision,null,null);
  if(!n.valid||!n.command) return _auResult(n.issues,{proposal:null,status:'REJECTED'});
  const cmd=Object.assign({},n.command);
  cmd.source='AI_PROPOSAL'; cmd.status='PENDING';
  const ident={type:cmd.type,target_id:cmd.target_id,parameters:cmd.parameters,
    constraints:cmd.constraints,base_revision:cmd.base_revision};
  cmd.command_hash=_auSha16(ident);
  cmd.command_id='cmd:'+cmd.command_hash;
  return _auResult([],{proposal:{status:'PROPOSED_AUTHORING_COMMAND',committed:false,
    command:cmd,rationale:(typeof rationale==='string')?rationale:null,
    requires_explicit_confirmation:true,
    note:'a proposal is not a commit. It carries no privileged path: the same schema, '+
         'normaliser, validator, revision guard and preview apply, and an explicit '+
         'confirmation token is required before it may be committed.'}}); }

function auResolveNlTarget(model,phrase,buildingId){
  const bid=buildingId||'bld_0';
  if(typeof phrase!=='string'||!phrase.trim())
    return _auResult([_auIssue('INVALID_TARGET',phrase,
      'an empty phrase resolves to nothing')],{target:null,candidates:[]});
  const needle=phrase.trim().toLowerCase();
  const hits=[];
  _auAllRooms(model).forEach(p=>{
    const rid=String(p[1].id||''), name=String(p[1].name||'');
    if(needle===rid.toLowerCase()||needle===name.toLowerCase()
       ||rid.toLowerCase().indexOf(needle)>=0
       ||(name&&name.toLowerCase().indexOf(needle)>=0))
      hits.push(_auSpaceKey(bid,p[0],rid)); });
  const uniq=Array.from(new Set(hits)).sort(_scmp);
  if(!uniq.length) return _auResult([_auIssue('INVALID_TARGET',phrase,
    'no space matches this phrase')],{target:null,candidates:[]});
  if(uniq.length>1) return _auResult([_auIssue('AMBIGUOUS_TARGET',phrase,
    uniq.length+' spaces match; the caller must choose')],{target:null,candidates:uniq});
  return _auResult([],{target:uniq[0],candidates:uniq}); }

/* ------------------------------------------------------ الحفظ والتحميل - */
function auSerialiseProject(project,includeHistory,includeRevisionModels){
  const out={schema:AU_SCHEMA,version:AU_VERSION,engine_version:AU_ENGINE_VERSION,
    building_id:project.building_id,model:_auCopy(project.model),
    model_hash:project.model_hash,current_revision:project.current_revision};
  if(includeHistory!==false){
    out.history=_auCopy(project.history);
    out.audit_log=_auCopy(project.audit_log); }
  if(includeRevisionModels&&project.revision_models)
    out.revision_models=_auCopy(project.revision_models);
  out.note='the current canonical model and its revision pointer. No runtime state, no '+
    'camera, no selection, no portal state and no preview is serialised.';
  return out; }

function auLoadProject(payload,buildingId){
  const issues=[];
  if(!payload||typeof payload!=='object'||Array.isArray(payload))
    return _auResult([_auIssue('MODEL_INTEGRITY_FAILURE','payload',
      'a serialised project must be an object')],{project:null});
  const model=payload.model;
  if(!model||typeof model!=='object'||Array.isArray(model))
    return _auResult([_auIssue('MODEL_INTEGRITY_FAILURE','model',
      'the payload carries no canonical model')],{project:null});
  const bid=buildingId||payload.building_id||'bld_0';
  const identityIssues=auOpeningIdentityIssues(model,bid);
  if(identityIssues.length) return _auResult(identityIssues,{project:null,runtime_state_restored:false});
  const h=auModelHash(model,'building',bid);
  if(payload.model_hash&&payload.model_hash!==h)
    issues.push(_auIssue('MODEL_INTEGRITY_FAILURE','model_hash',
      'the stored hash does not match the stored model'));
  const proj={schema:AU_SCHEMA,version:AU_VERSION,engine_version:AU_ENGINE_VERSION,
    building_id:bid,model:_auCopy(model),model_hash:h,
    current_revision:(payload.current_revision===undefined)?null:payload.current_revision,
    history:_auCopy(payload.history||[]),audit_log:_auCopy(payload.audit_log||[]),
    revision_models:_auCopy(payload.revision_models||{}),
    authoring:{base_revision:(payload.current_revision===undefined)?null
      :payload.current_revision,working_revision:null,pending_commands:[],
      preview:null,validation:[],transaction_status:'IDLE',history:[]},
    note:'loaded project; runtime state starts fresh and is never restored from a saved model'};
  return _auResult(issues,{project:proj,runtime_state_restored:false}); }

function auSummary(project){
  const m=project.model;
  const rooms=_auAllRooms(m);
  const cnt=key=>rooms.reduce((s,p)=>s+((p[1][key]||[]).length),0);
  return {schema:AU_SCHEMA,version:AU_VERSION,building_id:project.building_id,
    model_hash:_auShort(project.model_hash),current_revision:project.current_revision,
    revisions:project.history.length,audit_entries:project.audit_log.length,
    levels:(m.levels||[]).length,spaces:rooms.length,
    doors:cnt('doors'),windows:cnt('windows'),objects:cnt('objects'),
    locks:Object.keys(m._authoring_locks||{}).length,
    transaction_status:project.authoring.transaction_status,
    writes_to_model_outside_authoring:false,compliance:'NOT_EVALUATED'}; }

/* -------------------------------------------------- مقبض التحويل ------- */
function auGizmoToCommand(op,targetId,delta){
  /* المقبض ينتج أمراً مصنّفاً، لا تحويلاً مباشراً على شبكة مضلّعات. */
  const o=_auEnum(op);
  if(ACS_AUTHORING_SPEC.implemented_gizmo_operations.indexOf(o)<0)
    return _auResult([_auIssue('COMMAND_NOT_IMPLEMENTED',op,
      'this gizmo operation is declared but not implemented in this phase')],{command:null});
  if(o!=='TRANSLATE')
    return _auResult([_auIssue('COMMAND_NOT_IMPLEMENTED',op,'only translation is supported')],
      {command:null});
  const d=delta||{};
  return _auResult([],{command:{type:'MOVE_OBJECT',target_id:targetId,
    parameters:{x:_auNum(d.x),z:_auNum(d.z)},source:'USER'},
    note:'a transform handle is converted into a typed domain command; a wall, door or '+
         'window is never scaled as a generic mesh'}); }


/* ---------------------- واجهة المطوّر لطبقة التأليف --------------------- */
if(typeof window!=='undefined'){
  window.ACS = window.ACS || {};
  window.ACS.authoringSpec    = ()=>_auCopy(ACS_AUTHORING_SPEC);
  window.ACS.createProject    = (m,bid,src,actor)=>auCreateProject(m,bid,src,actor);
  window.ACS.authoringState   = (p)=>auAuthoringState(p);
  window.ACS.beginEdit        = (p)=>auBeginEdit(p);
  window.ACS.previewCommand   = (m,c,rev,bid,snap,grid)=>auPreviewCommand(m,c,rev,bid,snap,grid);
  window.ACS.validateCommand  = (c,rev)=>auNormaliseCommand(c,rev,null,null);
  window.ACS.validateTransaction = (p,cs,bid)=>auValidateTransaction(p,cs,bid);
  window.ACS.commitTransaction= (p,cs,opts)=>auCommitTransaction(p,cs,opts);
  window.ACS.cancelEdit       = (p)=>auCancelPreview(p);
  window.ACS.undo             = (p,rev,at,bid)=>auUndo(p,rev,at,bid);
  window.ACS.redo             = (p,rev,at,bid)=>auRedo(p,rev,at,bid);
  window.ACS.revisionHistory  = (p)=>_auCopy(p.history);
  window.ACS.auditLog         = (p)=>_auCopy(p.audit_log);
  window.ACS.revisionDiff     = (a,b)=>auRevisionDiff(a,b);
  window.ACS.editableProperties = (m,id,bid)=>auEditableProperties(m,id,bid);
  window.ACS.dependencyImpact = (c,m,bid)=>auDependencyImpact(c,m,bid);
  window.ACS.proposeCommand   = (c,why,rev)=>auProposeCommand(c,why,rev);
  window.ACS.resolveEditTarget= (m,p,bid)=>auResolveNlTarget(m,p,bid);
  window.ACS.validateModel    = (m,bid)=>auValidateModelIntegrity(m,bid);
  window.ACS.serialiseProject = (p,h,r)=>auSerialiseProject(p,h,r);
  window.ACS.loadProject      = (x,bid)=>auLoadProject(x,bid);
  window.ACS.authoringSummary = (p)=>auSummary(p);
  window.ACS.gizmoToCommand   = (op,id,d)=>auGizmoToCommand(op,id,d);
  window.ACS.commandHash      = (c,rev)=>auCommandHash(c,rev);
}

